// FX-26's forms of processes that are calls (C101), at the types FX-26's
// checker gives them: a call headed by one is the form, whatever a program
// binds the name to, as FX-26 parses it; `send` and `receive` are no
// values, and `icell-get` and `icell-put!` are the primitives too.
pub fn process_forms() -> Str {
    str_lit("(send (poly ((r region) (m type)) (subr (send r) ((addr m r) m) unit)))\n   (receive (poly ((r region) (m type)) (subr (maxeff (receive r) nondet) ((inbox m r)) m)))\n   (icell-get (poly ((r region) (t type)) (subr (await r) ((icell t r)) t)))\n   (icell-put! (poly ((r region) (t type)) (subr (init r) ((icell t r) t) unit)))")
}

// kayak-rt's primitives at KFX's types: the prelude's (kfx/prelude.fx), and
// FX-26's standard environment's at `acyclic`, where making and reading
// lists are pure.
pub fn prelude() -> Str {
    str_lit("(string-length-i64 (subr pure (string) i64)) (string-ref-i64 (subr pure (string i64) char))\n   (char->i64 (subr pure (char) i64)) (i64->char (subr pure (i64) char)) (i64->string (subr pure (i64) string))\n   (make-flatarray-i64 (poly ((r region)) (subr (alloc r) (i64 i64) (flatarrayof i64 r))))\n   (flatarray-ref-i64 (poly ((r region)) (subr (read r) ((flatarrayof i64 r) i64) i64)))\n   (flatarray-set-i64! (poly ((r region)) (subr (write r) ((flatarrayof i64 r) i64 i64) unit)))\n   (flatarray-length-i64 (poly ((r region)) (subr pure ((flatarrayof i64 r)) i64)))")
}

// The prelude's (kfx/prelude.fx), at the types it gives them. To FX-26
// they are globals, the prelude's definitions: calling one reads it.
pub fn table_binds(v: &'static Cv, table: Str, file: Str, wher: Str) -> Binds {
    map(lambda1s(move |p: &'static Sexp| {
        let xs = items(p);
        bind(name_of(v, car(xs)), parse_scheme_of(v, second(xs), false), wher)
    }), read_all(string_chars(table), file, 1i64))
}

pub fn prim_binds(v: &'static Cv) -> Binds {
    onto(table_binds(v, primitives(), str_lit("kayak-rt's primitives"), str_lit("prim")), onto(map(lambda1s(move |b: &'static Bind| {
        let tagcase_ = b;
        match *tagcase_ {
            Bind::Bind(n, sc, w) => {
                bind(string_append(str_lit("%form "), n), sc, w)
            }
        }
    }), table_binds(v, process_forms(), str_lit("FX-26's processes"), str_lit("prim"))), table_binds(v, prelude(), str_lit("kfx/prelude.fx"), str_lit("global"))))
}

pub fn head_name(v: &'static Cv, head: &'static Sexp) -> Str {
    let tagcase_ = head;
    match *tagcase_ {
        Sexp::Lst(xs, src_file, src_line, src_pos) => {
            name_of(v, car(xs))
        }
        _ => {
            let other = tagcase_;
            name_of(v, other)
        }
    }
}

/// A define-datatype's name, parameters and variants, whose fields'
/// types may name the parameters; no two tags camel-cased alike in Rust.
pub fn datatype_of(v: &'static Cv, xs: Sexps) -> &'static Dt {
    if repeated_p(map(lambda1s(move |vt: &'static Sexp| {
        variant_name({
            let tagcase_ = car(items(vt));
            match *tagcase_ {
                Sexp::Sym(n, at_file, at_pos) => {
                    n
                }
                _ => {
                    let other = tagcase_;
                    str_lit("")
                }
            }
        })
    }), cdr(xs))) {
        match refuse(v, str_lit("two tags of one datatype named alike in Rust (camel-cased)")) {}
    } else {
        let params = family_params(v, car(xs));
        dt(head_name(v, car(xs)), params, map(lambda1s(move |vt: &'static Sexp| {
            let ys = items(vt);
            variant(name_of(v, car(ys)), parse_types(v, params, cdr(ys)))
        }), cdr(xs)))
    }
}

pub fn constructors(d: &'static Dt) -> Binds {
    let tagcase_ = d;
    match *tagcase_ {
        Dt::Dt(name, ps, vs) => {
            map(lambda1s(move |vt: &'static Variant| {
                let tagcase_ = vt;
                match *tagcase_ {
                    Variant::Variant(tag, fields) => {
                        bind(tag, scheme(ps, ty_proc(nil::<Str>(), fields, ty_data(name, map(lambda1s(move |p: Str| {
                            ty_var(p)
                        }), ps)))), str_lit("global"))
                    }
                }
            }), vs)
        }
    }
}

// Types and datatypes are declared ahead: every one is in scope in every
// definition, as FX-26 has it. Effect abbreviations and values are seen
// only after their definitions.
/// A define-type's or define-datatype's name, from its head: a name, or
/// `(name (p kind) ...)` for a family.
pub fn type_name(v: &'static Cv, form: &'static Sexp) -> Str {
    let tagcase_ = form;
    match *tagcase_ {
        Sexp::Lst(xs, src_file, src_line, src_pos) => {
            head_name(near(v, src_file, src_line, src_pos), second(xs))
        }
        _ => {
            let other = tagcase_;
            match refuse(v, str_lit("a definition is expected")) {}
        }
    }
}

pub fn type_params(v: &'static Cv, form: &'static Sexp) -> Strings {
    let tagcase_ = form;
    match *tagcase_ {
        Sexp::Lst(xs, src_file, src_line, src_pos) => {
            family_params(near(v, src_file, src_line, src_pos), second(xs))
        }
        _ => {
            let other = tagcase_;
            nil::<Str>()
        }
    }
}

/// Text's lines, those not empty, as `cs` and the line so far, reversed.
pub fn lines_of(mut cs: List<char>, mut line: List<char>) -> Strings {
    loop {
        if null_p(cs) {
            if null_p(line) {
                return nil::<Str>();
            } else {
                return kayak_rt::heap_cons(rev_to_string(line), kayak_rt::nil());
            }
        } else if char_eq_p(car(cs), '\n') {
            if null_p(line) {
                (cs, line) = (cdr(cs), nil::<char>());
                continue;
            } else {
                return kayak_rt::heap_cons(rev_to_string(line), lines_of(cdr(cs), nil::<char>()));
            }
        } else {
            (cs, line) = (cdr(cs), kayak_rt::heap_cons(car(cs), line));
            continue;
        }
    }
}

/// `(define-convention name clause ...)` (C116, Fixpt's TODO §97): its
/// name, if its clauses, each printed as Fixpt prints it, are in any
/// order those of the native convention (`native-convention-text`,
/// Fixpt's, which kayak-jit keeps); else refused. The convention it names
/// is then `native`.
pub fn declared_convention(v: &'static Cv, xs: Sexps) -> Str {
    if (i64_lt(size(xs), 3i64) || not({
        let tagcase_ = second(xs);
        match *tagcase_ {
            Sexp::Sym(n, f, p) => {
                true
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    })) {
        match refuse(v, str_lit("(define-convention name clause ...)")) {}
    } else if not(strings_eq_p(sorted_strings(map(&show_sexp, cdr(cdr(xs)))), sorted_strings(lines_of(string_to_list(native_convention_text()), nil::<char>())))) {
        match refuse(v, string_append(str_lit("a convention not the native one, which alone this implementation supports: "), sym_name(second(xs)))) {}
    } else {
        sym_name(second(xs))
    }
}

pub fn declare_types(mut v: &'static Cv, mut forms: Sexps, mut als: Aliases) -> Aliases {
    loop {
        if null_p(forms) {
            return als;
        } else if head_is_p(car(forms), str_lit("define-type")) {
            let xs = items(car(forms));
            (forms, als) = (cdr(forms), kayak_rt::heap_cons(alias(type_name(v, car(forms)), type_params(v, car(forms)), third(xs)), als));
            continue;
        } else if head_is_p(car(forms), str_lit("define-convention")) {
            // A convention's name (C116), `%conv name`, standing for `native`.
            let n = {
                let tagcase_ = car(forms);
                match *tagcase_ {
                    Sexp::Lst(xs, f, l, p) => {
                        declared_convention(near(v, f, l, p), xs)
                    }
                    _ => {
                        let other = tagcase_;
                        declared_convention(v, items(other))
                    }
                }
            };
            (forms, als) = (cdr(forms), kayak_rt::heap_cons(alias(string_append(str_lit("%conv "), n), nil::<Str>(), sym(str_lit("native"), str_lit(""), 0i64)), als));
            continue;
        } else {
            forms = cdr(forms);
            continue;
        }
    }
}

/// The datatypes' names, before their variants' types can be read.
pub fn datatype_names(mut v: &'static Cv, mut forms: Sexps, mut ds: Dts) -> Dts {
    loop {
        if null_p(forms) {
            return ds;
        } else if (head_is_p(car(forms), str_lit("define-datatype")) || head_is_p(car(forms), str_lit("define-generative"))) {
            (forms, ds) = (cdr(forms), kayak_rt::heap_cons(dt(type_name(v, car(forms)), type_params(v, car(forms)), nil::<&'static Variant>()), ds));
            continue;
        } else {
            forms = cdr(forms);
            continue;
        }
    }
}

/// `v`, with a define-effect's abbreviation.
pub fn with_effdef(v: &'static Cv, xs: Sexps) -> &'static Cv {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, als, es, here, group, file, line, fs, tv, at) => {
            cv(bs, ds, als, kayak_rt::heap_cons(effdef(name_of(v, second(xs)), parse_effect(v, nil::<Str>(), third(xs))), es), here, group, file, line, fs, tv, at)
        }
    }
}

pub fn selects_p(e: &'static Sexp) -> bool {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Lst(xs, f, l, p) => {
            (sym_is_p(car(xs), str_lit("select")) || any_p(&selects_p, xs))
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// Each datatype's variants' types, as an effect abbreviation before it
/// has them read.
pub fn declare_datatypes(mut v: &'static Cv, mut forms: Sexps, mut ds: Dts) -> Dts {
    loop {
        if null_p(forms) {
            return ds;
        } else if head_is_p(car(forms), str_lit("define-datatype")) {
            (forms, ds) = (cdr(forms), kayak_rt::heap_cons(datatype_of(v, cdr(items(car(forms)))), ds));
            continue;
        } else if head_is_p(car(forms), str_lit("define-generative")) {
            (forms, ds) = (cdr(forms), kayak_rt::heap_cons(dt(type_name(v, car(forms)), type_params(v, car(forms)), nil::<&'static Variant>()), ds));
            continue;
        } else if (head_is_p(car(forms), str_lit("define-effect")) && not(selects_p(car(forms)))) {
            // An effect abbreviation, for the datatypes' fields' types; one that
            // selects a module's is read where it stands, after the module.
            (v, forms) = (with_effdef(v, items(car(forms))), cdr(forms));
            continue;
        } else {
            forms = cdr(forms);
            continue;
        }
    }
}

pub fn at(v: &'static Cv, here: Str, group: Strings) -> &'static Cv {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, als, es, h, g, file, line, fs, tv, at) => {
            cv(bs, ds, als, es, here, group, file, line, fs, tv, at)
        }
    }
}

/// kayak-rt's own names, which the generated modules import with the
/// program's: a global of one of them would be ambiguous in Rust.
pub fn runtime_name_p(name: Str) -> bool {
    (string_eq_p(name, str_lit("alloc")) || string_eq_p(name, str_lit("leak-string")) || string_eq_p(name, str_lit("with-big-stack")) || string_eq_p(name, str_lit("abort-current-continuation")) || string_eq_p(name, str_lit("make-continuation-prompt-tag")) || string_eq_p(name, str_lit("the")) || string_eq_p(name, str_lit("unwind")) || string_eq_p(name, str_lit("knot")) || string_eq_p(name, str_lit("lambda0")) || string_eq_p(name, str_lit("lambda1")) || string_eq_p(name, str_lit("lambda2")) || string_eq_p(name, str_lit("lambda3")) || string_eq_p(name, str_lit("lambda4")))
}

pub fn scheme_text(sc: &'static Scheme) -> Str {
    let tagcase_ = sc;
    match *tagcase_ {
        Scheme::Scheme(tvars, t) => {
            string_append(words_of(tvars), string_append(str_lit(" | "), show_ty(st(nil::<&'static Sb>(), 0i64, nil::<&'static Fact>()), t)))
        }
    }
}

/// A global. FX-26 may define a name again, at the same type (C61), and
/// what used it sees the new one; at another type its users would break,
/// which FX-26 says at their use, and the checker here at the
/// redefinition, so that the two still refuse the one program. KFX
/// defines each name once, and none kayak-rt has: the restriction pass's
/// (restrict.kfx), as the generated modules each import every other's
/// names and kayak-rt's. A module's item may shadow a primitive or a
/// global (C87), as FX-26's may, and as a Rust `mod`'s item shadows what
/// it imports by a glob.
pub fn global(v: &'static Cv, name: Str, sc: &'static Scheme) -> &'static Bind {
    if (keyword_p(name) && null_p(find_bind(str_lit("%module"), cv_binds(v)))) {
        match refuse(v, string_append(str_lit("a keyword names nothing: "), name)) {}
    } else {
        let found = find_bind(name, cv_binds(v));
        if null_p(found) {
            bind(name, sc, if null_p(find_bind(str_lit("%module"), cv_binds(v))) {
                str_lit("global")
            } else {
                str_lit("item")
            })
        } else {
            let tagcase_ = car(found);
            match *tagcase_ {
                Bind::Bind(n, sc0, wher) => {
                    if (string_eq_p(scheme_text(sc0), scheme_text(sc)) || (not(null_p(find_bind(str_lit("%module"), cv_binds(v)))) && (string_eq_p(wher, str_lit("prim")) || string_eq_p(wher, str_lit("global"))))) {
                        bind(name, sc, if null_p(find_bind(str_lit("%module"), cv_binds(v))) {
                            str_lit("global")
                        } else {
                            str_lit("item")
                        })
                    } else {
                        match refuse(v, string_append(name, str_lit(" is defined again, at another type, which would break what uses it"))) {}
                    }
                }
            }
        }
    }
}

/// A `define-generative`'s conversions, `up-t` from what it is made of and
/// `down-t` back: a new type, distinct from its representation, as
/// FX-26's top-level generative type is (not abstract: anyone may convert).
pub fn conversions(v: &'static Cv, xs: Sexps) -> Binds {
    let name = head_name(v, second(xs));
    let params = family_params(v, second(xs));
    let made = ty_data(name, map(lambda1s(move |p: Str| {
        ty_var(p)
    }), params));
    let repr = parse_type(with_tvars(v, params), params, third(xs));
    kayak_rt::heap_cons(bind(string_append(str_lit("up-"), name), scheme(params, ty_proc(nil::<Str>(), kayak_rt::heap_cons(repr, kayak_rt::nil()), made)), str_lit("global")), kayak_rt::heap_cons(bind(string_append(str_lit("down-"), name), scheme(params, ty_proc(nil::<Str>(), kayak_rt::heap_cons(made, kayak_rt::nil()), repr)), str_lit("global")), kayak_rt::nil()))
}

/// `v` with each of `bs`, each refused if its name is taken (`global`).
pub fn defined_once(mut v: &'static Cv, mut bs: Binds) -> &'static Cv {
    loop {
        if null_p(bs) {
            return v;
        } else {
            let tagcase_ = car(bs);
            match *tagcase_ {
                Bind::Bind(n, sc, wher) => {
                    (v, bs) = (with_binds(v, kayak_rt::heap_cons(global(v, n, sc), kayak_rt::nil())), cdr(bs));
                    continue;
                }
            }
        }
    }
}

pub fn new_state() -> &'static St {
    st(nil::<&'static Sb>(), 0i64, nil::<&'static Fact>())
}

/// `v`, with a definition's facts.
pub fn with_facts(v: &'static Cv, more: Facts) -> &'static Cv {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, als, es, here, group, file, line, fs, tv, at) => {
            cv(bs, ds, als, es, here, group, file, line, onto(more, fs), tv, at)
        }
    }
}

/// A global whose latent effect reads itself, or a member of its group,
/// may reach itself through the store: its type says `spin`, as FX-26's
/// must (`no_reaching_itself`).
pub fn no_reaching_itself(v: &'static Cv, group: Strings, sc: &'static Scheme) -> &'static Cv {
    let tagcase_ = sc;
    match *tagcase_ {
        Scheme::Scheme(tvars, t) => {
            let tagcase_ = t;
            match *tagcase_ {
                Ty::TyProc(es, ps, r) => {
                    if (not(string_member_p(str_lit("spin"), es)) && any_p(lambda1s(move |n: Str| {
                        string_member_p(string_append(str_lit("g:"), n), es)
                    }), group)) {
                        match refuse(v, string_append(str_lit("calling it reads "), string_append(words_of(group), str_lit(": it may reach itself through a global, so its type must say spin")))) {}
                    } else {
                        v
                    }
                }
                _ => {
                    let other = tagcase_;
                    v
                }
            }
        }
    }
}

/// Whether a definition of one procedure ends however it calls itself, so
/// that its calls of itself need no `spin` (`terminates?`).
pub fn ends_alone_p(v: &'static Cv, name: Str, sc: &'static Scheme, defined: &'static Sexp) -> bool {
    let tagcase_ = sc;
    match *tagcase_ {
        Scheme::Scheme(tvars, t) => {
            termination::terminates_p(v, kayak_rt::heap_cons(name, kayak_rt::nil()), kayak_rt::heap_cons(t, kayak_rt::nil()), kayak_rt::heap_cons(defined, kayak_rt::nil()))
        }
    }
}

/// Whether `e` makes a list, `list` or `cons`: an acyclic one's making
/// has no effect, but a constant of one is made once all the same, not
/// at each use (`rust-keywords`), FX-26's list being immutable.
pub fn makes_pairs_p(e: &'static Sexp) -> bool {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Lst(xs, file, line, pos) => {
            (not(null_p(xs)) && (sym_is_p(car(xs), str_lit("list")) || sym_is_p(car(xs), str_lit("cons")) || any_p(&makes_pairs_p, cdr(xs))))
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// A constant's value, of effect `es`: it may read globals, and allocate,
/// and is then made once, at its first use, and kept (C21), which the
/// emitter is told; nothing else, since when it is made is not when
/// FX-26 makes it, where it is defined.
pub fn constant_made(v: &'static Cv, s: &'static St, e: &'static Sexp, es: Strings, t: &'static Ty) -> &'static St {
    if any_p(lambda1s(move |x: Str| {
        not((string_eq_p(x, str_lit("spin")) || string_eq_p(x, str_lit("@globals")) || global_atom_p(x) || has_prefix_p(x, str_lit("alloc:"))))
    }), es) {
        match refuse(v, string_append(str_lit("a constant whose value has the effect "), string_append(show_effs(es), str_lit(": KFX makes a constant at its first use, so its value may only read globals and allocate")))) {}
    } else if (not(null_p(find_bind(str_lit("%loaded"), cv_binds(v)))) && any_p(lambda1s(move |x: Str| {
        not((string_eq_p(x, str_lit("@globals")) || global_atom_p(x)))
    }), es)) {
        // In a file loaded (C88): FX-26 makes it once, for all its loads, so
        // making it must be pure but for reading globals.
        match refuse(v, string_append(str_lit("a loaded file is one value for all its loads, made once, so making it must be pure, and this one has "), string_append(show_effs(es), str_lit(": make its state in a `lambda` it gives, which each caller applies")))) {}
    } else if (any_p(lambda1s(move |x: Str| {
        has_prefix_p(x, str_lit("alloc:"))
    }), es) || makes_pairs_p(e)) {
        // Kept for the whole program if its type's Rust is `Sync`, which a
        // process may hold; else for each thread, which none may (C102).
        let tagcase_ = e;
        match *tagcase_ {
            Sexp::Lst(xs, file, line, pos) => {
                let s = note_fact(s, file, pos, str_lit("once"));
                if expressions::sync_type_p(v, s, t, nil::<Str>()) {
                    note_fact(s, file, pos, str_lit("shared"))
                } else {
                    s
                }
            }
            _ => {
                let other = tagcase_;
                s
            }
        }
    } else {
        s
    }
}

/// The places a procedure is given, `%place 'p` each, from its
/// parameters' types: where its body may write `(place p)` (C34).
pub fn place_marks_of(t: &'static Ty) -> Strings {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyProc(es, ps, r) => {
            concat(map(lambda1s(move |p: &'static Ty| {
                let tagcase_ = p;
                match *tagcase_ {
                    Ty::TyData(d, args) => {
                        if string_eq_p(d, str_lit("%place")) {
                            let tagcase_ = car(args);
                            match *tagcase_ {
                                Ty::TyVar(n) => {
                                    the::<Strings>(kayak_rt::heap_cons(string_append(str_lit("%place "), n), kayak_rt::nil()))
                                }
                                _ => {
                                    let other = tagcase_;
                                    nil::<Str>()
                                }
                            }
                        } else {
                            nil::<Str>()
                        }
                    }
                    _ => {
                        let other = tagcase_;
                        nil::<Str>()
                    }
                }
            }), ps))
        }
        _ => {
            let other = tagcase_;
            nil::<Str>()
        }
    }
}

/// A procedure's lambda against its type; `v` already has its name.
pub fn check_procedure(v: &'static Cv, defined: &'static Sexp, sc: &'static Scheme) -> &'static Cv {
    let (lam, v) = (items(if head_is_p(defined, str_lit("plambda")) {
        third(items(defined))
    } else {
        defined
    }), with_binds(v, kayak_rt::heap_cons(bind(str_lit("%toplambda"), scheme(nil::<Str>(), ty_unit()), str_lit("yes")), kayak_rt::nil())));
    let tagcase_ = sc;
    match *tagcase_ {
        Scheme::Scheme(tvars, t) => {
            let tagcase_ = expressions::check_lambda(with_tvars(v, onto(place_marks_of(t), tvars)), new_state(), items(second(lam)), cdr(cdr(lam)), t);
            match *tagcase_ {
                Res::Res(u, es, s) => {
                    with_facts(v, expressions::settle_facts(s))
                }
            }
        }
    }
}

pub fn variants_dt(v: &'static Cv, d: Str) -> &'static Dt {
    let found = find_family(d, cv_dts(v));
    if kayak_rt::value::null_p(found) {
        match refuse(v, string_append(str_lit("no datatype is named "), d)) {}
    } else {
        kayak_rt::value::unbox_other::<&'static Dt>(found)
    }
}

/// A define-rec's members, one by one, each one's facts kept: `group`,
/// those whose calls are recursion (none if the group ends); `names`, all
/// of them, whose reading is reaching itself, ending or not.
pub fn check_members(mut v: &'static Cv, mut bindings: Sexps, mut group: Strings, mut names: Strings) -> &'static Cv {
    loop {
        if null_p(bindings) {
            return v;
        } else {
            let ys = items(car(bindings));
            if lambda_form_p(third(ys)) {
                (v, bindings) = (check_procedure(no_reaching_itself(at(v, name_of(v, car(ys)), group), names, parse_scheme(v, second(ys))), third(ys), parse_scheme(v, second(ys))), cdr(bindings));
                continue;
            } else {
                return match refuse(v, str_lit("a define-rec binds only lambdas")) {};
            }
        }
    }
}

pub fn first_n(fs: Facts, n: i64) -> Facts {
    if (null_p(fs) || i64_lt(n, 1i64)) {
        nil::<&'static Fact>()
    } else {
        kayak_rt::heap_cons(car(fs), first_n(cdr(fs), i64_minus(n, 1i64)))
    }
}

pub fn chars_before(mut cs: Chars, mut c: char, mut acc: Chars) -> Str {
    loop {
        if (null_p(cs) || char_eq_p(car(cs), c)) {
            return rev_to_string(acc);
        } else {
            (cs, acc) = (cdr(cs), kayak_rt::heap_cons(car(cs), acc));
            continue;
        }
    }
}

pub fn before_char(s: Str, c: char) -> Str {
    chars_before(string_chars(s), c, nil::<char>())
}

/// A fact of a making in, or a need of, one of `places`, as `'p kind T`;
/// or ``. The facts are `rheld-kind@'p T` and `rneed-kind@'p T`.
pub fn place_need(what: Str, places: Strings) -> Str {
    let held = if has_prefix_p(what, str_lit("rheld-")) {
        after_prefix(what, str_lit("rheld-"))
    } else if has_prefix_p(what, str_lit("rneed-")) {
        after_prefix(what, str_lit("rneed-"))
    } else {
        str_lit("")
    };
    let kind = before_char(held, '@');
    let rest = after_prefix(held, string_append(kind, str_lit("@")));
    let place = before_char(rest, ' ');
    if (not(string_eq_p(held, str_lit(""))) && string_member_p(place, places)) {
        string_append(place, string_append(str_lit(" "), string_append(kind, string_append(str_lit(" "), after_prefix(rest, string_append(place, str_lit(" ")))))))
    } else {
        str_lit("")
    }
}

/// A procedure given places (C34): what it makes in each, by itself or by
/// the procedures it gives the place to, kept as `place-needs name 'p
/// kind T` at its definition, for its calls and for the Rust it is: a
/// place's type, a type parameter bound to hold each.
pub fn with_place_needs(v: &'static Cv, name: Str, sc: &'static Scheme, before: i64, file: Str, pos: i64) -> &'static Cv {
    let places = concat(map(lambda1s(move |m: Str| {
        the::<Strings>(kayak_rt::heap_cons(after_prefix(m, str_lit("%place ")), kayak_rt::nil()))
    }), place_marks_of({
        let tagcase_ = sc;
        match *tagcase_ {
            Scheme::Scheme(tv, t) => {
                t
            }
        }
    })));
    let fs = cv_facts(v);
    let new = first_n(fs, i64_minus(size(fs), before));
    if null_p(places) {
        v
    } else {
        with_facts(v, concat(map(lambda1s(move |f: &'static Fact| {
            let tagcase_ = f;
            match *tagcase_ {
                Fact::Fact(ff, fp, what) => {
                    let need = place_need(what, places);
                    if string_eq_p(need, str_lit("")) {
                        nil::<&'static Fact>()
                    } else {
                        the::<Facts>(kayak_rt::heap_cons(fact(file, pos, string_append(str_lit("place-needs "), string_append(name, string_append(str_lit(" "), need)))), kayak_rt::nil()))
                    }
                }
            }
        }), new)))
    }
}

/// `s`'s words, split at spaces.
pub fn split_words_check(s: Str) -> Strings {
    map(lambda1s(move |x: &'static Sexp| {
        sym_name(x)
    }), read_all(string_chars(s), str_lit(""), 1i64))
}

/// A define-rec's procedures given places (C34): its members call each
/// other before any one's needs are summed, so each is given all the
/// group makes in a place of its name, by any member: more bounds than
/// some need, which Rust takes, since every caller then holds them.
pub fn with_group_needs(v: &'static Cv, bindings: Sexps, before: i64) -> &'static Cv {
    let fs = cv_facts(v);
    let new = first_n(fs, i64_minus(size(fs), before));
    let members = map(lambda1s(move |b: &'static Sexp| {
        let ys = items(b);
        fact(datum_file(b), datum_pos(b), string_append(sym_name(car(ys)), string_append(str_lit(" "), words_of(map(lambda1s(move |m: Str| {
            after_prefix(m, str_lit("%place "))
        }), place_marks_of({
            let tagcase_ = parse_scheme(v, second(ys));
            match *tagcase_ {
                Scheme::Scheme(tv, t) => {
                    t
                }
            }
        }))))))
    }), bindings);
    let all_places = concat(map(lambda1s(move |m: &'static Fact| {
        let tagcase_ = m;
        match *tagcase_ {
            Fact::Fact(f, p, w) => {
                cdr(split_words_check(w))
            }
        }
    }), members));
    let needs = concat(map(lambda1s(move |f: &'static Fact| {
        let tagcase_ = f;
        match *tagcase_ {
            Fact::Fact(ff, fp, what) => {
                let n = place_need(what, all_places);
                if string_eq_p(n, str_lit("")) {
                    nil::<Str>()
                } else {
                    the::<Strings>(kayak_rt::heap_cons(n, kayak_rt::nil()))
                }
            }
        }
    }), new));
    if null_p(all_places) {
        v
    } else {
        with_facts(v, concat(map(lambda1s(move |m: &'static Fact| {
            let tagcase_ = m;
            match *tagcase_ {
                Fact::Fact(f, p, w) => {
                    let ws = split_words_check(w);
                    let mine = cdr(ws);
                    concat(map(lambda1s(move |n: Str| {
                        if string_member_p(before_char(n, ' '), mine) {
                            the::<Facts>(kayak_rt::heap_cons(fact(f, p, string_append(str_lit("place-needs "), string_append(car(ws), string_append(str_lit(" "), n)))), kayak_rt::nil()))
                        } else {
                            nil::<&'static Fact>()
                        }
                    }), needs))
                }
            }
        }), members)))
    }
}

/// A define-rec: every member in scope in each, and each a lambda.
pub fn check_rec(v: &'static Cv, bindings: Sexps) -> &'static Cv {
    let names = map(lambda1s(move |b: &'static Sexp| {
        name_of(v, car(items(b)))
    }), bindings);
    let ends = termination::terminates_p(v, names, map(lambda1s(move |b: &'static Sexp| {
        let tagcase_ = parse_scheme(v, second(items(b)));
        match *tagcase_ {
            Scheme::Scheme(tvars, t) => {
                t
            }
        }
    }), bindings), map(lambda1s(move |b: &'static Sexp| {
        third(items(b))
    }), bindings));
    let named = with_binds(v, map(lambda1s(move |b: &'static Sexp| {
        let ys = items(b);
        global(v, name_of(v, car(ys)), parse_scheme(v, second(ys)))
    }), bindings));
    with_group_needs(check_members(named, bindings, if ends {
        nil::<Str>()
    } else {
        names
    }, names), bindings, size(cv_facts(named)))
}

pub fn global_reads(mut es: Strings) -> Strings {
    loop {
        if null_p(es) {
            return nil::<Str>();
        } else {
            if (string_eq_p(car(es), str_lit("@globals")) || global_atom_p(car(es))) {
                return kayak_rt::heap_cons(car(es), global_reads(cdr(es)));
            } else {
                es = cdr(es);
                continue;
            }
        }
    }
}

/// `(define* name type lambda)`: as FX-26 has it, the globals its body
/// reads are found, not written. The body is checked as though the type
/// read every global, and a call of itself read itself (C71: FX-26's
/// effect, `(read (globals name))`, not every global's); the global is then of the type written, its effect
/// with the globals found. A place it is given is as a `define`'s: what
/// it makes there kept (C34).
pub fn check_define_star(v: &'static Cv, xs: Sexps, src_file: Str, src_pos: i64) -> &'static Cv {
    let name = name_of(v, second(xs));
    let defined = fourth(xs);
    let v = at(v, name, if ends_alone_p(v, name, parse_scheme(v, third(xs)), defined) {
        nil::<Str>()
    } else {
        kayak_rt::heap_cons(name, kayak_rt::nil())
    });
    let lam = items(if head_is_p(defined, str_lit("plambda")) {
        third(items(defined))
    } else {
        defined
    });
    if not(lambda_form_p(defined)) {
        match refuse(v, str_lit("a define* is of a lambda")) {}
    } else {
        let tagcase_ = parse_scheme(v, third(xs));
        match *tagcase_ {
            Scheme::Scheme(tvars, t) => {
                let tagcase_ = t;
                match *tagcase_ {
                    Ty::TyProc(declared, ps, r) => {
                        let wide = ty_proc(effs_union(kayak_rt::heap_cons(str_lit("@globals"), kayak_rt::nil()), declared), ps, r);
                        let itself = ty_proc(effs_union(kayak_rt::heap_cons(string_append(str_lit("g:"), name), kayak_rt::nil()), declared), ps, r);
                        let named = with_binds(v, kayak_rt::heap_cons(global(v, name, scheme(tvars, itself)), kayak_rt::nil()));
                        let found = expressions::lambda_effects(with_tvars(with_tvars(named, tvars), place_marks(third(xs))), new_state(), items(second(lam)), cdr(cdr(lam)), wide);
                        let es = {
                            let tagcase_ = found;
                            match *tagcase_ {
                                Res::Res(u, es, s) => {
                                    es
                                }
                            }
                        };
                        let fs = {
                            let tagcase_ = found;
                            match *tagcase_ {
                                Res::Res(u, es, s) => {
                                    expressions::settle_facts(s)
                                }
                            }
                        };
                        if effs_within_p(es, effs_union(kayak_rt::heap_cons(str_lit("@globals"), kayak_rt::nil()), declared)) {
                            let sc = scheme(tvars, ty_proc(effs_union(global_reads(es), declared), ps, r));
                            let w = with_binds(no_reaching_itself(v, kayak_rt::heap_cons(name, kayak_rt::nil()), sc), kayak_rt::heap_cons(global(v, name, sc), kayak_rt::nil()));
                            with_facts(with_place_needs(with_facts(w, fs), name, sc, size(cv_facts(w)), src_file, src_pos), concat(map(lambda1s(move |m: Str| {
                                if has_prefix_p(m, str_lit("%within ")) {
                                    the::<Facts>(kayak_rt::heap_cons(fact(src_file, src_pos, string_append(str_lit("region-within "), string_append(name, string_append(str_lit(" "), after_prefix(m, str_lit("%within ")))))), kayak_rt::nil()))
                                } else {
                                    nil::<&'static Fact>()
                                }
                            }), place_marks(third(xs)))))
                        } else {
                            match refuse(v, string_append(str_lit("a define* whose effect "), string_append(show_effs(es), string_append(str_lit(" is not within "), show_effs(declared))))) {}
                        }
                    }
                    _ => {
                        let other = tagcase_;
                        match refuse(v, str_lit("a define* is of a procedure")) {}
                    }
                }
            }
        }
    }
}

/// One top-level form, which may add to what the forms after it see.
pub fn check_top(v: &'static Cv, form: &'static Sexp) -> &'static Cv {
    let tagcase_ = form;
    match *tagcase_ {
        Sexp::Str(x, at_file, at_pos) => {
            v
        }
        Sexp::Lst(xs, src_file, src_line, src_pos) => {
            let (v, h) = (near(v, src_file, src_line, src_pos), if null_p(xs) {
                str_lit("")
            } else {
                let tagcase_ = car(xs);
                match *tagcase_ {
                    Sexp::Sym(n, at_file, at_pos) => {
                        n
                    }
                    _ => {
                        let other = tagcase_;
                        str_lit("")
                    }
                }
            });
            if string_eq_p(h, str_lit("define-effect")) {
                with_effdef(v, xs)
            } else if string_eq_p(h, str_lit("define-convention")) {
                v
            } else if string_eq_p(h, str_lit("define-type")) {
                // Its body read where it stands, used or not: so that one that
                // mentions itself, or names no type, is refused.
                if head_is_p(third(xs), str_lit("moduleof")) {
                    expressions::spec_well_formed(v, third(xs));
                    expressions::module_type_values(expressions::module_scope(v, third(xs), str_lit(""), str_lit("")), third(xs));
                    v
                } else if (head_is_p(third(xs), str_lit("select")) && {
                    let found = find_alias(string_append(name_of(v, second(items(third(xs)))), string_append(str_lit(" "), name_of(v, third(items(third(xs)))))), cv_aliases(v));
                    (not(null_p(found)) && {
                        let tagcase_ = car(found);
                        match *tagcase_ {
                            Alias::Alias(n, ps, b) => {
                                not(null_p(ps))
                            }
                        }
                    })
                }) {
                    // An abbreviation of a module's family (C89): read where applied.
                    v
                } else {
                    let name = head_name(v, second(xs));
                    let params = family_params(v, second(xs));
                    let body = parse_type(v, kayak_rt::heap_cons(string_append(str_lit("%expanding "), name), onto(map(lambda1s(move |p: Str| {
                        string_append(str_lit("%place "), p)
                    }), concat(map(lambda1s(move |p: Str| {
                        if has_prefix_p(p, str_lit("'")) {
                            the::<Strings>(kayak_rt::heap_cons(p, kayak_rt::nil()))
                        } else {
                            nil::<Str>()
                        }
                    }), params))), params)), third(xs));
                    v
                }
            } else if string_eq_p(h, str_lit("define-datatype")) {
                let d = variants_dt(v, head_name(v, second(xs)));
                defined_once(v, constructors(d))
            } else if string_eq_p(h, str_lit("define-generative")) {
                defined_once(v, conversions(v, xs))
            } else if string_eq_p(h, str_lit("define")) {
                if not(i64_eq(size(xs), 4i64)) {
                    match refuse(v, str_lit("a definition needs a type")) {}
                } else {
                    let name = name_of(v, second(xs));
                    let sc = parse_scheme(v, third(xs));
                    let v = at(v, name, if ends_alone_p(v, name, sc, fourth(xs)) {
                        nil::<Str>()
                    } else {
                        kayak_rt::heap_cons(name, kayak_rt::nil())
                    });
                    let v = no_reaching_itself(v, kayak_rt::heap_cons(name, kayak_rt::nil()), sc);
                    let named = with_binds(v, kayak_rt::heap_cons(global(v, name, sc), kayak_rt::nil()));
                    if lambda_form_p(fourth(xs)) {
                        with_facts(with_place_needs(check_procedure(with_tvars(named, place_marks(third(xs))), fourth(xs), sc), name, sc, size(cv_facts(named)), src_file, src_pos), onto(concat(map(lambda1s(move |m: Str| {
                            if has_prefix_p(m, str_lit("%within ")) {
                                the::<Facts>(kayak_rt::heap_cons(fact(src_file, src_pos, string_append(str_lit("region-within "), string_append(name, string_append(str_lit(" "), after_prefix(m, str_lit("%within ")))))), kayak_rt::nil()))
                            } else {
                                nil::<&'static Fact>()
                            }
                        }), place_marks(third(xs)))), {
                            let tagcase_ = third(xs);
                            match *tagcase_ {
                                Sexp::Sym(n, f, p) => {
                                    let tagcase_ = sc;
                                    match *tagcase_ {
                                        Scheme::Scheme(tvars, t) => {
                                            the::<Facts>(kayak_rt::heap_cons(fact(datum_file(fourth(xs)), datum_pos(fourth(xs)), string_append(str_lit("def-type "), show_ty(new_state(), t))), kayak_rt::nil()))
                                        }
                                    }
                                }
                                _ => {
                                    let other = tagcase_;
                                    nil::<&'static Fact>()
                                }
                            }
                        }))
                    } else {
                        let tagcase_ = sc;
                        match *tagcase_ {
                            Scheme::Scheme(tvars, t) => {
                                if null_p(tvars) {
                                    let tagcase_ = expressions::check(v, new_state(), fourth(xs), t);
                                    match *tagcase_ {
                                        Res::Res(u, es, s) => {
                                            with_facts(named, expressions::settle_facts(constant_made(v, s, fourth(xs), es, t)))
                                        }
                                    }
                                } else {
                                    match refuse(v, str_lit("a poly constant: only a procedure may be poly")) {}
                                }
                            }
                        }
                    }
                }
            } else if string_eq_p(h, str_lit("define-rec")) {
                check_rec(v, cdr(xs))
            } else if string_eq_p(h, str_lit("define*")) {
                check_define_star(v, xs, src_file, src_pos)
            } else {
                let tagcase_ = expressions::synth(at(v, str_lit("a top-level expression"), nil::<Str>()), new_state(), form);
                match *tagcase_ {
                    Res::Res(t, es, s) => {
                        with_facts(v, expressions::settle_facts({
                            let s = if suspends_p(es) {
                                note_fact(s, src_file, src_pos, str_lit("suspends"))
                            } else {
                                s
                            };
                            if void_p(s, t) {
                                note_fact(s, src_file, src_pos, str_lit("void"))
                            } else if proc_type_p(s, t) {
                                note_fact(s, src_file, src_pos, str_lit("procedure"))
                            } else {
                                s
                            }
                        }))
                    }
                }
            }
        }
        _ => {
            let other = tagcase_;
            let tagcase_ = expressions::synth(at(v, str_lit("a top-level expression"), nil::<Str>()), new_state(), form);
            match *tagcase_ {
                Res::Res(t, es, s) => {
                    with_facts(v, expressions::settle_facts(if proc_type_p(s, t) {
                        note_fact(s, datum_file(form), datum_pos(form), str_lit("procedure"))
                    } else {
                        s
                    }))
                }
            }
        }
    }
}

/// The names an item defines: values and types.
pub fn item_names(f: &'static Sexp) -> Strings {
    if (head_is_p(f, str_lit("define")) || head_is_p(f, str_lit("define*")) || head_is_p(f, str_lit("define-type")) || head_is_p(f, str_lit("define-generative"))) {
        let tagcase_ = second(items(f));
        match *tagcase_ {
            Sexp::Sym(n, at_file, at_pos) => {
                the::<Strings>(kayak_rt::heap_cons(n, kayak_rt::nil()))
            }
            _ => {
                let other = tagcase_;
                nil::<Str>()
            }
        }
    } else if head_is_p(f, str_lit("define-rec")) {
        map(lambda1s(move |b: &'static Sexp| {
            sym_name(car(items(b)))
        }), cdr(items(f)))
    } else if head_is_p(f, str_lit("define-datatype")) {
        let tagcase_ = second(items(f));
        match *tagcase_ {
            Sexp::Sym(n, at_file, at_pos) => {
                the::<Strings>(kayak_rt::heap_cons(n, kayak_rt::nil()))
            }
            _ => {
                let other = tagcase_;
                nil::<Str>()
            }
        }
    } else {
        nil::<Str>()
    }
}

pub fn module_def_p(form: &'static Sexp) -> bool {
    (head_is_p(form, str_lit("define")) && i64_eq(size(items(form)), 3i64) && (head_is_p(third(items(form)), str_lit("module")) || head_is_p(third(items(form)), str_lit("extend"))))
}

/// Module items without their strings, a `hide`'s too: FX-26's, a string
/// among a module's items is a comment (Fixpt, 2026-10-12).
pub fn uncommented(forms: Sexps) -> Sexps {
    concat(map(lambda1s(move |f: &'static Sexp| {
        let tagcase_ = f;
        match *tagcase_ {
            Sexp::Str(s, file, pos) => {
                nil::<&'static Sexp>()
            }
            Sexp::Lst(xs, file, line, pos) => {
                if head_is_p(f, str_lit("hide")) {
                    the::<Sexps>(kayak_rt::heap_cons(lst(kayak_rt::heap_cons(car(xs), uncommented(cdr(xs))), file, line, pos), kayak_rt::nil()))
                } else {
                    the::<Sexps>(kayak_rt::heap_cons(f, kayak_rt::nil()))
                }
            }
            _ => {
                let other = tagcase_;
                the::<Sexps>(kayak_rt::heap_cons(f, kayak_rt::nil()))
            }
        }
    }), forms))
}

// `(extend e0 e1)` (C87, FX-91's): a module of both's values and types,
// `e1`'s where both give a name; `e1` sees `e0`'s, its own shadowing them.
// KFX's, of an `e0` defined at the top level: the module `(include e0
// (except ...))` then `e1`'s items, or `(include e1)` if `e1` is a name: the
// names `e1` gives are not taken from `e0`. So the Rust is a `mod` of `pub
// use`s, and its own items, which Rust's scope lets shadow a glob's.
/// A module definition's items, as written, or as its `extend` is, its
/// strings among them: what the emitter writes, each string a comment.
pub fn module_noted(form: &'static Sexp) -> Sexps {
    let x = third(items(form));
    if head_is_p(x, str_lit("module")) {
        cdr(items(x))
    } else {
        let tagcase_ = x;
        match *tagcase_ {
            Sexp::Lst(xs, file, line, pos) => {
                let (e0, e1) = (second(xs), third(xs));
                if not(i64_eq(size(xs), 3i64)) {
                    error(str_lit("kfx: an extend of two modules"))
                } else if not({
                    let tagcase_ = e0;
                    match *tagcase_ {
                        Sexp::Sym(n, f, p) => {
                            true
                        }
                        _ => {
                            let other = tagcase_;
                            false
                        }
                    }
                }) {
                    error(str_lit("kfx: an extend of a module made where it is extended, which KFX does not have yet: its first module is one defined at the top level"))
                } else if {
                    let tagcase_ = e1;
                    match *tagcase_ {
                        Sexp::Sym(n, f, p) => {
                            true
                        }
                        _ => {
                            let other = tagcase_;
                            false
                        }
                    }
                } {
                    kayak_rt::heap_cons(lst(kayak_rt::heap_cons(sym(str_lit("include"), file, pos), kayak_rt::heap_cons(e0, kayak_rt::heap_cons(lst(kayak_rt::heap_cons(sym(str_lit("except-module"), file, pos), kayak_rt::heap_cons(e1, kayak_rt::nil())), file, line, pos), kayak_rt::nil()))), file, line, pos), kayak_rt::heap_cons(lst(kayak_rt::heap_cons(sym(str_lit("include"), file, pos), kayak_rt::heap_cons(e1, kayak_rt::nil())), file, line, pos), kayak_rt::nil()))
                } else if head_is_p(e1, str_lit("module")) {
                    let own = cdr(items(e1));
                    kayak_rt::heap_cons(lst(kayak_rt::heap_cons(sym(str_lit("include"), file, pos), kayak_rt::heap_cons(e0, kayak_rt::heap_cons(lst(kayak_rt::heap_cons(sym(str_lit("except"), file, pos), map(lambda1s(move |n: Str| {
                        sym(n, file, pos)
                    }), concat(map(&item_names, concat(map(lambda1s(move |g: &'static Sexp| {
                        if head_is_p(g, str_lit("hide")) {
                            cdr(items(g))
                        } else {
                            the::<Sexps>(kayak_rt::heap_cons(g, kayak_rt::nil()))
                        }
                    }), uncommented(own))))))), file, line, pos), kayak_rt::nil()))), file, line, pos), own)
                } else {
                    error(str_lit("kfx: an extend's second module is a name or a module"))
                }
            }
            _ => {
                let other = tagcase_;
                nil::<&'static Sexp>()
            }
        }
    }
}

/// A module definition's items, as written, or as its `extend` is, without
/// the strings among them.
pub fn module_written(form: &'static Sexp) -> Sexps {
    uncommented(module_noted(form))
}

/// An `include`'s exception, `(except n ...)` or `(except-module m)`, as a
/// list of one, or none.
pub fn include_except(f: &'static Sexp) -> Sexps {
    if i64_gt(size(items(f)), 2i64) {
        the::<Sexps>(kayak_rt::heap_cons(third(items(f)), kayak_rt::nil()))
    } else {
        nil::<&'static Sexp>()
    }
}

/// The names of the types and modules `forms` define, one Rust scope's.
pub fn type_level_names(forms: Sexps) -> Strings {
    concat(map(lambda1s(move |f: &'static Sexp| {
        if (head_is_p(f, str_lit("define-type")) || head_is_p(f, str_lit("define-datatype")) || head_is_p(f, str_lit("define-generative"))) {
            let tagcase_ = second(items(f));
            match *tagcase_ {
                Sexp::Sym(n, at_file, at_pos) => {
                    the::<Strings>(kayak_rt::heap_cons(n, kayak_rt::nil()))
                }
                Sexp::Lst(ys, fl, ln, ps) => {
                    let tagcase_ = car(ys);
                    match *tagcase_ {
                        Sexp::Sym(n, at_file, at_pos) => {
                            the::<Strings>(kayak_rt::heap_cons(n, kayak_rt::nil()))
                        }
                        _ => {
                            let other = tagcase_;
                            nil::<Str>()
                        }
                    }
                }
                _ => {
                    let other = tagcase_;
                    nil::<Str>()
                }
            }
        } else if module_def_p(f) {
            the::<Strings>(kayak_rt::heap_cons(sym_name(second(items(f))), kayak_rt::nil()))
        } else {
            nil::<Str>()
        }
    }), forms))
}

/// Each Rust scope's type and module names: the program's, then each module's.
pub fn type_scopes(forms: Sexps) -> List<Strings> {
    kayak_rt::heap_cons(type_level_names(forms), concat(map(lambda1s(move |f: &'static Sexp| {
        if module_def_p(f) {
            the::<List<Strings>>(kayak_rt::heap_cons(type_level_names(concat(map(lambda1s(move |g: &'static Sexp| {
                if head_is_p(g, str_lit("hide")) {
                    cdr(items(g))
                } else {
                    the::<Sexps>(kayak_rt::heap_cons(g, kayak_rt::nil()))
                }
            }), module_written(f)))), kayak_rt::nil()))
        } else {
            nil::<List<Str>>()
        }
    }), forms)))
}

/// The form among `forms`, or in their modules, that defines the type or
/// module `name`: a list of it, or none.
pub fn type_namer(mut forms: Sexps, mut name: Str) -> Sexps {
    loop {
        if null_p(forms) {
            return nil::<&'static Sexp>();
        } else if string_member_p(name, type_level_names(kayak_rt::heap_cons(car(forms), kayak_rt::nil()))) {
            return kayak_rt::heap_cons(car(forms), kayak_rt::nil());
        } else if module_def_p(car(forms)) {
            let inner = type_namer(concat(map(lambda1s(move |g: &'static Sexp| {
                if head_is_p(g, str_lit("hide")) {
                    cdr(items(g))
                } else {
                    the::<Sexps>(kayak_rt::heap_cons(g, kayak_rt::nil()))
                }
            }), module_written(car(forms)))), name);
            if null_p(inner) {
                forms = cdr(forms);
                continue;
            } else {
                return inner;
            }
        } else {
            forms = cdr(forms);
            continue;
        }
    }
}

/// `v` at the form that defines the type or module `name`, if one does.
pub fn type_namer_near(v: &'static Cv, forms: Sexps, name: Str) -> &'static Cv {
    let fs = type_namer(forms, name);
    if null_p(fs) {
        v
    } else {
        let tagcase_ = car(fs);
        match *tagcase_ {
            Sexp::Lst(xs, file, line, pos) => {
                near(v, file, line, pos)
            }
            _ => {
                let other = tagcase_;
                v
            }
        }
    }
}

/// The labels of every product and sum written in `es`, types and
/// `product` forms alike, each a shape the Rust names by its labels.
pub fn label_lists(es: Sexps) -> List<Strings> {
    concat(map(lambda1s(move |e: &'static Sexp| {
        let tagcase_ = e;
        match *tagcase_ {
            Sexp::Lst(xs, f, l, p) => {
                let here = if (not(null_p(xs)) && (sym_is_p(car(xs), str_lit("productof")) || sym_is_p(car(xs), str_lit("sumof")) || sym_is_p(car(xs), str_lit("product"))) && not(null_p(cdr(xs))) && not(any_p(lambda1s(move |x: &'static Sexp| {
                    let tagcase_ = x;
                    match *tagcase_ {
                        Sexp::Lst(ys, f2, l2, p2) => {
                            null_p(ys)
                        }
                        _ => {
                            let other = tagcase_;
                            true
                        }
                    }
                }), cdr(xs)))) {
                    the::<List<Strings>>(kayak_rt::heap_cons(map(lambda1s(move |x: &'static Sexp| {
                        let tagcase_ = car(items(x));
                        match *tagcase_ {
                            Sexp::Sym(n, f3, p3) => {
                                n
                            }
                            _ => {
                                let other = tagcase_;
                                str_lit("")
                            }
                        }
                    }), cdr(xs)), kayak_rt::nil()))
                } else {
                    nil::<List<Str>>()
                };
                onto(here, label_lists(xs))
            }
            _ => {
                let other = tagcase_;
                nil::<List<Str>>()
            }
        }
    }), es))
}

/// No two shapes of different labels named alike in Rust, their labels
/// mangled (`a?` and `a-p` are both `a_p`).
pub fn shapes_apart(v: &'static Cv, forms: Sexps) -> () {
    let lists = label_lists(forms);
    if any_p(lambda1s(move |ls: Strings| {
        any_p(lambda1s(move |ms: Strings| {
            (not(string_eq_p(words_of(ls), words_of(ms))) && string_eq_p(words_of(map(&mangle, ls)), words_of(map(&mangle, ms))))
        }), lists)
    }), lists) {
        match refuse(v, str_lit("two products or sums whose labels are one in Rust, mangled (`a?` and `a-p` are both `a_p`)")) {}
    } else {
        ()
    }
}

/// Types' names as FX-26 has them; as Rust has them (none named as a type
/// the generated Rust names, kayak-rt's `Str` and the few of Rust's it
/// writes; KFX's names, C27; none two in Rust) is the restriction
/// pass's (restrict.kfx, C61).
pub fn type_names_free(v: &'static Cv, forms: Sexps) -> () {
    shapes_apart(v, forms);
    map(lambda1s(move |f: &'static Sexp| {
        if ((head_is_p(f, str_lit("define-type")) || head_is_p(f, str_lit("define-datatype")) || head_is_p(f, str_lit("define-generative"))) && string_member_p({
            let tagcase_ = second(items(f));
            match *tagcase_ {
                Sexp::Sym(n, at_file, at_pos) => {
                    n
                }
                Sexp::Lst(ys, fl, ln, ps) => {
                    let tagcase_ = car(ys);
                    match *tagcase_ {
                        Sexp::Sym(n, at_file, at_pos) => {
                            n
                        }
                        _ => {
                            let other = tagcase_;
                            str_lit("")
                        }
                    }
                }
                _ => {
                    let other = tagcase_;
                    str_lit("")
                }
            }
        }, concat(map(lambda1s(move |g: &'static Sexp| {
            if head_is_p(g, str_lit("define-effect")) {
                let tagcase_ = second(items(g));
                match *tagcase_ {
                    Sexp::Sym(n, at_file, at_pos) => {
                        the::<Strings>(kayak_rt::heap_cons(n, kayak_rt::nil()))
                    }
                    _ => {
                        let other = tagcase_;
                        nil::<Str>()
                    }
                }
            } else {
                nil::<Str>()
            }
        }), forms)))) {
            let tagcase_ = f;
            match *tagcase_ {
                Sexp::Lst(xs, file, line, pos) => {
                    match refuse(near(v, file, line, pos), str_lit("a type named as an effect: FX-26's are one namespace, the effect hiding the type")) {}
                }
                _ => {
                    let other = tagcase_;
                    ()
                }
            }
        } else {
            ()
        }
    }), forms);
    map(lambda1s(move |f: &'static Sexp| {
        if ((head_is_p(f, str_lit("define-type")) || head_is_p(f, str_lit("define-datatype"))) && {
            let tagcase_ = second(items(f));
            match *tagcase_ {
                Sexp::Lst(ys, fl, ln, ps) => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }) {
            let tagcase_ = f;
            match *tagcase_ {
                Sexp::Lst(xs, file, line, pos) => {
                    let v = near(v, file, line, pos);
                    type_binders_apart(v, family_params(v, second(xs)), concat(type_scopes(forms)))
                }
                _ => {
                    let other = tagcase_;
                    ()
                }
            }
        } else {
            ()
        }
    }), forms);
    ()
}

// Elaboration. A definition with no type, `(define x e)`, has the type the
// checker finds for `e`; the emitter, which knows no types, is told it, as
// though it had been written. It is never `poly`, and must be known whole.
pub enum Typed {
    Typed(Str, &'static Sexp),
}

pub fn typed(f0: Str, f1: &'static Sexp) -> &'static Typed {
    kayak_rt::heap_alloc(Typed::Typed(f0, f1))
}

pub type Typeds = List<&'static Typed>;

pub enum Elab {
    Elab(&'static Cv, Typeds),
}

pub fn elab(f0: &'static Cv, f1: Typeds) -> &'static Elab {
    kayak_rt::heap_alloc(Elab::Elab(f0, f1))
}

/// `(with m y)`, `m` a module defined at the top level and `y` its poly
/// item: `y`'s scheme; else none (C107).
pub fn reexported(v: &'static Cv, e: &'static Sexp) -> List<&'static Scheme> {
    if (head_is_p(e, str_lit("with")) && i64_eq(size(items(e)), 3i64) && {
        let tagcase_ = second(items(e));
        match *tagcase_ {
            Sexp::Sym(n, f, p) => {
                true
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    } && {
        let tagcase_ = third(items(e));
        match *tagcase_ {
            Sexp::Sym(n, f, p) => {
                true
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    }) {
        let m = find_bind(sym_name(second(items(e))), cv_binds(v));
        if (null_p(m) || not({
            let tagcase_ = car(m);
            match *tagcase_ {
                Bind::Bind(n, sc, w) => {
                    string_eq_p(w, str_lit("module"))
                }
            }
        })) {
            nil::<&'static Scheme>()
        } else {
            let y = find_bind(sym_name(third(items(e))), opened_binds(sym_name(second(items(e))), cv_binds(v)));
            if null_p(y) {
                nil::<&'static Scheme>()
            } else {
                let tagcase_ = car(y);
                match *tagcase_ {
                    Bind::Bind(n, sc, w) => {
                        let tagcase_ = sc;
                        match *tagcase_ {
                            Scheme::Scheme(tvars, t) => {
                                if null_p(tvars) {
                                    nil::<&'static Scheme>()
                                } else {
                                    kayak_rt::heap_cons(sc, kayak_rt::nil())
                                }
                            }
                        }
                    }
                }
            }
        }
    } else {
        nil::<&'static Scheme>()
    }
}

/// `(define x e)`: `e`'s type found, `x` not in scope in `e` (as FX-26
/// has it, for a lambda too), and the type kept for the emitter.
pub fn check_untyped(v: &'static Cv, form: &'static Sexp) -> &'static Elab {
    let xs = items(form);
    let name = name_of(v, second(xs));
    let v = at(v, name, nil::<Str>());
    let e = third(xs);
    let again = reexported(v, e);
    if not(null_p(again)) {
        elab(with_binds(v, kayak_rt::heap_cons(global(v, name, car(again)), kayak_rt::nil())), kayak_rt::heap_cons(typed(name, lst(kayak_rt::heap_cons(sym(str_lit("%reexport"), str_lit(""), 0i64), kayak_rt::heap_cons(second(items(e)), kayak_rt::heap_cons(third(items(e)), kayak_rt::nil()))), str_lit(""), 0i64, 0i64)), kayak_rt::nil()))
    } else {
        let tagcase_ = expressions::synth(v, new_state(), e);
        match *tagcase_ {
            Res::Res(t, es, s) => {
                let (written, s) = (if expressions::has_var_p(s, t) {
                    match refuse(v, str_lit("a definition with no type, of a type over a binder: write its type")) {}
                } else {
                    expressions::ty_sexp(v, s, t)
                }, if lambda_form_p(e) {
                    s
                } else {
                    constant_made(v, s, e, es, t)
                });
                elab(with_facts(with_binds(v, kayak_rt::heap_cons(global(v, name, scheme(nil::<Str>(), zonk(s, t))), kayak_rt::nil())), expressions::settle_facts(s)), kayak_rt::heap_cons(typed(name, written), kayak_rt::nil()))
            }
        }
    }
}

// Modules (CLAUDES_CHOICES.md C19): `(define m (module item ...))` at the
// top level, a Rust `mod`. Its items are a program's definitions, each
// seeing those before it; its types are named `m..t` for the program, so
// that a module's and the program's never meet, and a generative type's
// conversions stay inside. Outside, `m`'s values and types are named `m x`,
// found by `with` and `select`.
pub fn tag_taken_p(tag: Str, ds: Dts) -> bool {
    any_p(lambda1s(move |d: &'static Dt| {
        let tagcase_ = d;
        match *tagcase_ {
            Dt::Dt(n, ps, vs) => {
                any_p(lambda1s(move |x: &'static Variant| {
                    let tagcase_ = x;
                    match *tagcase_ {
                        Variant::Variant(t, fs) => {
                            string_eq_p(t, tag)
                        }
                    }
                }), vs)
            }
        }
    }), ds)
}

/// A module's types' names, each refused if the program has a type of
/// that name; and the items KFX's modules do not have, refused.
pub fn module_types(mut v: &'static Cv, mut forms: Sexps) -> Strings {
    loop {
        if null_p(forms) {
            return nil::<Str>();
        } else {
            let f = car(forms);
            if (head_is_p(f, str_lit("define-datatype")) && any_p(lambda1s(move |vt: &'static Sexp| {
                tag_taken_p(sym_name(car(items(vt))), cv_dts(v))
            }), cdr(cdr(items(f))))) {
                return match refuse(v, str_lit("a module's datatype whose tag another datatype has: KFX's tags name one datatype each")) {};
            } else if (head_is_p(f, str_lit("define-type")) || head_is_p(f, str_lit("define-generative")) || head_is_p(f, str_lit("define-datatype"))) {
                let name = head_name(v, second(items(f)));
                if dt_named_p(name, cv_dts(v)) {
                    return match refuse(v, string_append(str_lit("a module's type named as the program's: KFX names them apart, "), name)) {};
                } else {
                    return kayak_rt::heap_cons(name, module_types(v, cdr(forms)));
                }
            } else if (head_is_p(f, str_lit("define-effect")) && i64_eq(size(items(f)), 3i64) && not(selects_p(f))) {
                // Each read with the module's effects before it (C116), one that may
                // abort too, as Fixpt's checker's `checks` does.
                (v, forms) = (with_effdef(v, items(f)), cdr(forms));
                continue;
            } else if (head_is_p(f, str_lit("define-effect")) && i64_eq(size(items(f)), 3i64) && escapes_p(parse_effect(v, nil::<Str>(), third(items(f))))) {
                return match refuse(v, str_lit("a module's effect that may abort, which KFX's modules do not have yet")) {};
            } else if head_is_p(f, str_lit("hide")) {
                return match refuse(v, string_append(str_lit("an item KFX's modules do not have yet: "), show_sexp(car(items(f))))) {};
            } else {
                forms = cdr(forms);
                continue;
            }
        }
    }
}

/// A type written in module `m`, its types named as the program names them;
/// `(select n u)` is `n`'s type `u`, no name of this module's (C88).
pub fn qualify_type(m: Str, names: Strings, t: &'static Sexp) -> &'static Sexp {
    let tagcase_ = t;
    match *tagcase_ {
        Sexp::Sym(n, at_file, at_pos) => {
            if string_member_p(n, names) {
                sym(string_append(m, string_append(str_lit(".."), n)), at_file, at_pos)
            } else {
                t
            }
        }
        Sexp::Lst(xs, file, line, pos) => {
            if head_is_p(t, str_lit("select")) {
                t
            } else {
                lst(map(lambda1s(move |x: &'static Sexp| {
                    qualify_type(m, names, x)
                }), xs), file, line, pos)
            }
        }
        _ => {
            let other = tagcase_;
            t
        }
    }
}

/// A module's types: each `m..t`; and `t` inside it, `m t` outside. A
/// family, `(t (p kind) ...)` (C89), the same, applied: `t` stands for
/// `(m..t p ...)`.
pub fn module_aliases(v: &'static Cv, m: Str, names: Strings, forms: Sexps, inside: bool) -> Aliases {
    concat(map(lambda1s(move |f: &'static Sexp| {
        if not((head_is_p(f, str_lit("define-type")) || head_is_p(f, str_lit("define-generative")) || head_is_p(f, str_lit("define-datatype")))) {
            nil::<&'static Alias>()
        } else {
            let xs = items(f);
            let t = head_name(v, second(xs));
            let ps = family_params(v, second(xs));
            let q = string_append(m, string_append(str_lit(".."), t));
            let name = if inside {
                t
            } else {
                string_append(m, string_append(str_lit(" "), t))
            };
            let named = alias(name, ps, if null_p(ps) {
                sym(q, str_lit(""), 0i64)
            } else {
                lst(kayak_rt::heap_cons(sym(q, str_lit(""), 0i64), map(lambda1s(move |p: Str| {
                    sym(if has_prefix_p(p, str_lit("'")) {
                        after_prefix(p, str_lit("'"))
                    } else {
                        p
                    }, str_lit(""), 0i64)
                }), ps)), str_lit(""), 0i64, 0i64)
            });
            if head_is_p(f, str_lit("define-type")) {
                the::<Aliases>(kayak_rt::heap_cons(named, kayak_rt::heap_cons(alias(q, ps, qualify_type(m, names, third(xs))), kayak_rt::nil())))
            } else {
                the::<Aliases>(kayak_rt::heap_cons(named, kayak_rt::nil()))
            }
        }
    }), forms))
}

pub fn module_dts(v: &'static Cv, m: Str, forms: Sexps) -> Dts {
    concat(map(lambda1s(move |f: &'static Sexp| {
        if (head_is_p(f, str_lit("define-generative")) || head_is_p(f, str_lit("define-datatype"))) {
            the::<Dts>(kayak_rt::heap_cons(dt(string_append(m, string_append(str_lit(".."), head_name(v, second(items(f))))), family_params(v, second(items(f))), nil::<&'static Variant>()), kayak_rt::nil()))
        } else {
            nil::<&'static Dt>()
        }
    }), forms))
}

/// A module's generative types' conversions, `up-t` and `down-t`: its
/// items', not in its type, so that outside `m..t` is abstract.
pub fn module_conversions(v: &'static Cv, m: Str, forms: Sexps) -> Binds {
    concat(map(lambda1s(move |f: &'static Sexp| {
        if head_is_p(f, str_lit("define-generative")) {
            let xs = items(f);
            let t = sym_name(second(xs));
            let made = ty_data(string_append(m, string_append(str_lit(".."), t)), nil::<&'static Ty>());
            let repr = parse_type(v, nil::<Str>(), third(xs));
            the::<Binds>(kayak_rt::heap_cons(bind(string_append(str_lit("up-"), t), scheme(nil::<Str>(), ty_proc(nil::<Str>(), kayak_rt::heap_cons(repr, kayak_rt::nil()), made)), str_lit("item")), kayak_rt::heap_cons(bind(string_append(str_lit("down-"), t), scheme(nil::<Str>(), ty_proc(nil::<Str>(), kayak_rt::heap_cons(made, kayak_rt::nil()), repr)), str_lit("item")), kayak_rt::nil())))
        } else {
            nil::<&'static Bind>()
        }
    }), forms))
}

/// A module's datatypes, their variants read where its types are named.
pub fn module_datatypes(v: &'static Cv, m: Str, forms: Sexps) -> Dts {
    concat(map(lambda1s(move |f: &'static Sexp| {
        if head_is_p(f, str_lit("define-datatype")) {
            let tagcase_ = datatype_of(v, cdr(items(f)));
            match *tagcase_ {
                Dt::Dt(n, ps, vs) => {
                    the::<Dts>(kayak_rt::heap_cons(dt(string_append(m, string_append(str_lit(".."), n)), ps, vs), kayak_rt::nil()))
                }
            }
        } else {
            nil::<&'static Dt>()
        }
    }), forms))
}

/// A module's effect abbreviations, as `m e`: what each is, as the module
/// read it.
pub fn module_effects(m: Str, forms: Sexps, es: Effdefs) -> Effdefs {
    concat(map(lambda1s(move |f: &'static Sexp| {
        if head_is_p(f, str_lit("define-effect")) {
            let name = sym_name(second(items(f)));
            concat(map(lambda1s(move |d: &'static Effdef| {
                let tagcase_ = d;
                match *tagcase_ {
                    Effdef::Effdef(n, atoms) => {
                        if string_eq_p(n, name) {
                            the::<Effdefs>(kayak_rt::heap_cons(effdef(string_append(m, string_append(str_lit(" "), n)), atoms), kayak_rt::nil()))
                        } else {
                            nil::<&'static Effdef>()
                        }
                    }
                }
            }), es))
        } else {
            nil::<&'static Effdef>()
        }
    }), forms))
}

/// The items' values, before the module's mark, as `m x`.
pub fn module_exports(mut m: Str, mut conversions: Strings, mut bs: Binds) -> Binds {
    loop {
        if null_p(bs) {
            return nil::<&'static Bind>();
        } else {
            let tagcase_ = car(bs);
            match *tagcase_ {
                Bind::Bind(n, sc, wher) => {
                    if string_eq_p(n, str_lit("%module")) {
                        return nil::<&'static Bind>();
                    } else if string_member_p(n, conversions) {
                        bs = cdr(bs);
                        continue;
                    } else {
                        return kayak_rt::heap_cons(bind(string_append(m, string_append(str_lit(" "), n)), sc, str_lit("export")), module_exports(m, conversions, cdr(bs)));
                    }
                }
            }
        }
    }
}

pub fn untyped_p(form: &'static Sexp) -> bool {
    (head_is_p(form, str_lit("define")) && i64_eq(size(items(form)), 3i64))
}

// A module's `(include n)` and `(hide item ...)` (FX-26's): an included
// module's values and types are the module's own, in scope in all its
// items, and in its type unless hidden; a hidden item is the module's, not
// in its type. The module included is one defined at the top level.
/// The items, those of a `hide` among them.
pub fn unhidden(forms: Sexps) -> Sexps {
    concat(map(lambda1s(move |f: &'static Sexp| {
        if head_is_p(f, str_lit("hide")) {
            cdr(items(f))
        } else {
            the::<Sexps>(kayak_rt::heap_cons(f, kayak_rt::nil()))
        }
    }), forms))
}

/// The names among `names` that `e` mentions (a local of the same name
/// taken for the item: more references, never fewer).
pub fn item_names_in(e: &'static Sexp, names: Strings) -> Strings {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Sym(n, f, p) => {
            if string_member_p(n, names) {
                the::<Strings>(kayak_rt::heap_cons(n, kayak_rt::nil()))
            } else {
                nil::<Str>()
            }
        }
        Sexp::Lst(xs, f, l, p) => {
            concat(map(lambda1s(move |x: &'static Sexp| {
                item_names_in(x, names)
            }), xs))
        }
        _ => {
            let other = tagcase_;
            nil::<Str>()
        }
    }
}

/// The values an item defines.
pub fn item_value_names(f: &'static Sexp) -> Strings {
    if (head_is_p(f, str_lit("define-type")) || head_is_p(f, str_lit("define-generative")) || head_is_p(f, str_lit("define-datatype"))) {
        nil::<Str>()
    } else {
        item_names(f)
    }
}

/// The types an item defines.
pub fn item_type_names(f: &'static Sexp) -> Strings {
    if (head_is_p(f, str_lit("define-type")) || head_is_p(f, str_lit("define-generative")) || head_is_p(f, str_lit("define-datatype"))) {
        item_names(f)
    } else {
        nil::<Str>()
    }
}

/// A type as written, a name of an abbreviation with no parameters
/// followed to what it stands for.
pub fn resolved_alias(mut body: &'static Sexp, mut als: Aliases) -> &'static Sexp {
    loop {
        let tagcase_ = body;
        match *tagcase_ {
            Sexp::Sym(n, f, p) => {
                let found = find_alias(n, als);
                if null_p(found) {
                    return body;
                } else {
                    let tagcase_ = car(found);
                    match *tagcase_ {
                        Alias::Alias(m, ps, b) => {
                            if null_p(ps) {
                                body = b;
                                continue;
                            } else {
                                return body;
                            }
                        }
                    }
                }
            }
            _ => {
                let other = tagcase_;
                return body;
            }
        }
    }
}

// A module's names: values and types named apart, as at the top level; a
// type two modules included both give is one where it is the same type
// both times (C86, FX-26's).
/// Aliases, one of each name that stands for the same type each time
/// (written alike, naming none of the types the modules give, which
/// could be two types written alike); else kept twice, and refused.
pub fn distinct_aliases(mut als: Aliases) -> Aliases {
    loop {
        if null_p(als) {
            return nil::<&'static Alias>();
        } else if any_p(lambda1s(move |b: &'static Alias| {
            let tagcase_ = car(als);
            match *tagcase_ {
                Alias::Alias(n, ps, body) => {
                    let tagcase_ = b;
                    match *tagcase_ {
                        Alias::Alias(m, qs, body2) => {
                            (string_eq_p(n, m) && string_eq_p(show_sexp(body), show_sexp(body2)) && null_p(item_names_in(body, map(lambda1s(move |a: &'static Alias| {
                                let tagcase_ = a;
                                match *tagcase_ {
                                    Alias::Alias(k, ks, kb) => {
                                        k
                                    }
                                }
                            }), als))))
                        }
                    }
                }
            }
        }), cdr(als)) {
            als = cdr(als);
            continue;
        } else {
            return kayak_rt::heap_cons(car(als), distinct_aliases(cdr(als)));
        }
    }
}

pub fn hidden_items(forms: Sexps) -> Sexps {
    concat(map(lambda1s(move |f: &'static Sexp| {
        if head_is_p(f, str_lit("hide")) {
            cdr(items(f))
        } else {
            nil::<&'static Sexp>()
        }
    }), forms))
}

/// The values hidden items define: a hidden datatype's constructors too.
/// A hidden type does not hide a value of its name, nor a value a type's
/// (C86, FX-26's).
pub fn hidden_value_names(forms: Sexps) -> Strings {
    concat(map(lambda1s(move |g: &'static Sexp| {
        if head_is_p(g, str_lit("define-datatype")) {
            map(lambda1s(move |x: &'static Sexp| {
                let tagcase_ = x;
                match *tagcase_ {
                    Sexp::Lst(ys, f, l, p) => {
                        sym_name(car(ys))
                    }
                    Sexp::Sym(n, f, p) => {
                        n
                    }
                    _ => {
                        let other = tagcase_;
                        str_lit("")
                    }
                }
            }), cdr(cdr(items(g))))
        } else {
            item_value_names(g)
        }
    }), hidden_items(forms)))
}

pub fn hidden_type_names(forms: Sexps) -> Strings {
    concat(map(&item_type_names, hidden_items(forms)))
}

/// Whether module `n` is one made in place, defined before its user as
/// `made--P` (C90), not a `load-input`'s module bound by name (C116).
pub fn made_in_place_p(n: Str) -> bool {
    (has_prefix_p(n, str_lit("made--")) && not(has_prefix_p(n, str_lit("made--input--"))))
}

/// A hidden datatype or generative type in a type the module shows is
/// refused, as FX-26 refuses it, for now (`modules/hide-escape.fx`).
pub fn hidden_escapes(v: &'static Cv, forms: Sexps) -> () {
    let r#abstract = concat(map(lambda1s(move |g: &'static Sexp| {
        if (head_is_p(g, str_lit("define-datatype")) || head_is_p(g, str_lit("define-generative"))) {
            item_names(g)
        } else if (head_is_p(g, str_lit("include")) && made_in_place_p(sym_name(second(items(g))))) {
            // A hidden include's abstract types are hidden too (C90), of a
            // module made in place, which are the includer's own; a named
            // module's stay its own, as FX-26 has it (C116: Fixpt's
            // `convention.fx`, its `let`'s module included).
            let n = sym_name(second(items(g)));
            concat(map(lambda1s(move |d: &'static Dt| {
                let tagcase_ = d;
                match *tagcase_ {
                    Dt::Dt(dn, ps, vs) => {
                        if has_prefix_p(dn, string_append(n, str_lit(".."))) {
                            the::<Strings>(kayak_rt::heap_cons(after_prefix(dn, string_append(n, str_lit(".."))), kayak_rt::nil()))
                        } else {
                            nil::<Str>()
                        }
                    }
                }
            }), cv_dts(v)))
        } else {
            nil::<Str>()
        }
    }), hidden_items(forms)));
    if null_p(r#abstract) {
        ()
    } else {
        map(lambda1s(move |f: &'static Sexp| {
            let ts = if (head_is_p(f, str_lit("define")) && i64_eq(size(items(f)), 4i64)) {
                the::<Sexps>(kayak_rt::heap_cons(third(items(f)), kayak_rt::nil()))
            } else if head_is_p(f, str_lit("define*")) {
                the::<Sexps>(kayak_rt::heap_cons(third(items(f)), kayak_rt::nil()))
            } else if head_is_p(f, str_lit("define-rec")) {
                map(lambda1s(move |b: &'static Sexp| {
                    second(items(b))
                }), cdr(items(f)))
            } else if head_is_p(f, str_lit("define-type")) {
                the::<Sexps>(kayak_rt::heap_cons(third(items(f)), kayak_rt::nil()))
            } else {
                nil::<&'static Sexp>()
            };
            if any_p(lambda1s(move |t: &'static Sexp| {
                not(null_p(item_names_in(t, r#abstract)))
            }), ts) {
                match refuse(v, string_append(str_lit("a hidden type in a type the module shows: "), words_of(r#abstract))) {}
            } else {
                ()
            }
        }), concat(map(lambda1s(move |f: &'static Sexp| {
            if head_is_p(f, str_lit("hide")) {
                nil::<&'static Sexp>()
            } else {
                the::<Sexps>(kayak_rt::heap_cons(f, kayak_rt::nil()))
            }
        }), forms)));
        ()
    }
}

/// The modules `forms` include, each defined at the top level.
pub fn included(v: &'static Cv, forms: Sexps) -> Strings {
    concat(map(lambda1s(move |f: &'static Sexp| {
        if head_is_p(f, str_lit("include")) {
            let n = name_of(v, second(items(f)));
            if (null_p(find_bind(n, cv_binds(v))) || not({
                let tagcase_ = car(find_bind(n, cv_binds(v)));
                match *tagcase_ {
                    Bind::Bind(x, sc, w) => {
                        string_eq_p(w, str_lit("module"))
                    }
                }
            })) {
                match refuse(v, string_append(str_lit("KFX includes a module defined at the top level, by its name: "), n)) {}
            } else {
                the::<Strings>(kayak_rt::heap_cons(n, kayak_rt::nil()))
            }
        } else {
            nil::<Str>()
        }
    }), forms))
}

/// The names an `include` of `n` among `written` does not take (C87): an
/// `extend`'s second module's.
pub fn except_names(v: &'static Cv, written: Sexps, n: Str) -> Strings {
    let incs = concat(map(lambda1s(move |f: &'static Sexp| {
        if (head_is_p(f, str_lit("include")) && string_eq_p(sym_name(second(items(f))), n)) {
            include_except(f)
        } else {
            nil::<&'static Sexp>()
        }
    }), onto(written, concat(map(lambda1s(move |f: &'static Sexp| {
        if head_is_p(f, str_lit("hide")) {
            cdr(items(f))
        } else {
            nil::<&'static Sexp>()
        }
    }), written)))));
    if null_p(incs) {
        nil::<Str>()
    } else {
        let x = car(incs);
        if head_is_p(x, str_lit("except-module")) {
            let b = sym_name(second(items(x)));
            onto(map(lambda1s(move |d: &'static Bind| {
                let tagcase_ = d;
                match *tagcase_ {
                    Bind::Bind(k, sc, w) => {
                        k
                    }
                }
            }), opened_binds(b, cv_binds(v))), map(lambda1s(move |a: &'static Alias| {
                let tagcase_ = a;
                match *tagcase_ {
                    Alias::Alias(k, ps, body) => {
                        k
                    }
                }
            }), expressions::opened_aliases(b, cv_aliases(v))))
        } else {
            map(&sym_name, cdr(items(x)))
        }
    }
}

pub fn excepted_binds(v: &'static Cv, written: Sexps, n: Str, bs: Binds) -> Binds {
    let ex = except_names(v, written, n);
    concat(map(lambda1s(move |d: &'static Bind| {
        let tagcase_ = d;
        match *tagcase_ {
            Bind::Bind(k, sc, w) => {
                if string_member_p(k, ex) {
                    nil::<&'static Bind>()
                } else {
                    the::<Binds>(kayak_rt::heap_cons(d, kayak_rt::nil()))
                }
            }
        }
    }), opened_binds(n, bs)))
}

// Each module a module includes, with the values it gives it, found once.
pub enum TypedBinds {
    TypedBinds(Str, Binds),
}

pub fn typed_binds(f0: Str, f1: Binds) -> &'static TypedBinds {
    kayak_rt::heap_alloc(TypedBinds::TypedBinds(f0, f1))
}

pub fn binds_of_include(mut n: Str, mut ibs: List<&'static TypedBinds>) -> Binds {
    loop {
        if null_p(ibs) {
            return nil::<&'static Bind>();
        } else if {
            let tagcase_ = car(ibs);
            match *tagcase_ {
                TypedBinds::TypedBinds(k, bs) => {
                    string_eq_p(k, n)
                }
            }
        } {
            let tagcase_ = car(ibs);
            match *tagcase_ {
                TypedBinds::TypedBinds(k, bs) => {
                    return bs;
                }
            }
        } else {
            ibs = cdr(ibs);
            continue;
        }
    }
}

pub fn excepted_aliases(v: &'static Cv, written: Sexps, n: Str, als: Aliases) -> Aliases {
    let ex = except_names(v, written, n);
    concat(map(lambda1s(move |a: &'static Alias| {
        let tagcase_ = a;
        match *tagcase_ {
            Alias::Alias(k, ps, body) => {
                if string_member_p(k, ex) {
                    nil::<&'static Alias>()
                } else {
                    the::<Aliases>(kayak_rt::heap_cons(a, kayak_rt::nil()))
                }
            }
        }
    }), expressions::opened_aliases(n, als)))
}

/// Module `m`'s effects, named as `m` names them: an `include` gives them
/// the module, as a `with` gives them its body (C87, FX-26's).
pub fn opened_effdefs(m: Str, es: Effdefs) -> Effdefs {
    concat(map(lambda1s(move |d: &'static Effdef| {
        let tagcase_ = d;
        match *tagcase_ {
            Effdef::Effdef(n, atoms) => {
                if has_prefix_p(n, string_append(m, str_lit(" "))) {
                    the::<Effdefs>(kayak_rt::heap_cons(effdef(after_prefix(n, string_append(m, str_lit(" "))), atoms), kayak_rt::nil()))
                } else {
                    nil::<&'static Effdef>()
                }
            }
        }
    }), es))
}

/// The modules included not in a `hide`: their types are the module's.
pub fn unhidden_includes(v: &'static Cv, written: Sexps) -> Strings {
    included(v, concat(map(lambda1s(move |f: &'static Sexp| {
        if head_is_p(f, str_lit("hide")) {
            nil::<&'static Sexp>()
        } else {
            the::<Sexps>(kayak_rt::heap_cons(f, kayak_rt::nil()))
        }
    }), written)))
}

/// Module `n`'s types, opened, as module `m`'s: `m t`.
pub fn renamed_aliases(n: Str, m: Str, als: Aliases) -> Aliases {
    map(lambda1s(move |a: &'static Alias| {
        let tagcase_ = a;
        match *tagcase_ {
            Alias::Alias(t, ps, body) => {
                alias(string_append(m, string_append(str_lit(" "), t)), ps, body)
            }
        }
    }), als)
}

/// A module's exported types, those hidden dropped.
pub fn without_aliases(hidden: Strings, m: Str, als: Aliases) -> Aliases {
    concat(map(lambda1s(move |a: &'static Alias| {
        let tagcase_ = a;
        match *tagcase_ {
            Alias::Alias(t, ps, body) => {
                if string_member_p(after_prefix(t, string_append(m, str_lit(" "))), hidden) {
                    nil::<&'static Alias>()
                } else {
                    the::<Aliases>(kayak_rt::heap_cons(a, kayak_rt::nil()))
                }
            }
        }
    }), als))
}

// A module's items as FX-26's `letrec*` (C85, docs/research/modules.md
// stage 1): a typed lambda may name any item, earlier or later; any other
// value is made when its item is, so what it names, and what the lambdas it
// names name, must be made before it. KFX checks the items in an order
// their references allow, each set of procedures that reach one another a
// `define-rec` (so `spin` and termination are as a group's); Rust's items
// are in no order, and the emitter writes them as they were.
pub enum Mitem {
    Mitem(&'static Sexp, Strings, Strings, bool),
}

pub fn mitem(f0: &'static Sexp, f1: Strings, f2: Strings, f3: bool) -> &'static Mitem {
    kayak_rt::heap_alloc(Mitem::Mitem(f0, f1, f2, f3))
}

pub type Mitems = List<&'static Mitem>;

/// A value item's value, under a `%found`, or none.
pub fn item_value(f: &'static Sexp) -> Sexps {
    let xs = items(f);
    if (head_is_p(f, str_lit("define")) && i64_eq(size(xs), 4i64)) {
        the::<Sexps>(kayak_rt::heap_cons(if head_is_p(fourth(xs), str_lit("%found")) {
            second(items(fourth(xs)))
        } else {
            fourth(xs)
        }, kayak_rt::nil()))
    } else if module_def_p(f) {
        // A module item is made where it is written (C88): what uses it
        // must come after it, as FX-26's `reexport-too-soon` has it.
        module_written(f)
    } else if (head_is_p(f, str_lit("define")) && i64_eq(size(xs), 3i64)) {
        the::<Sexps>(kayak_rt::heap_cons(third(xs), kayak_rt::nil()))
    } else if head_is_p(f, str_lit("define*")) {
        the::<Sexps>(kayak_rt::heap_cons(fourth(xs), kayak_rt::nil()))
    } else if head_is_p(f, str_lit("define-rec")) {
        map(lambda1s(move |b: &'static Sexp| {
            third(items(b))
        }), cdr(xs))
    } else {
        nil::<&'static Sexp>()
    }
}

pub fn nset_names(s: &'static Nset) -> Strings {
    let tagcase_ = s;
    match *tagcase_ {
        Nset::Nempty() => {
            nil::<Str>()
        }
        Nset::Nnode(l, k, r) => {
            onto(nset_names(l), kayak_rt::heap_cons(k, nset_names(r)))
        }
    }
}

pub fn nset_without(s: &'static Nset, out: Strings) -> &'static Nset {
    nset_of(concat(map(lambda1s(move |n: Str| {
        if string_member_p(n, out) {
            nil::<Str>()
        } else {
            the::<Strings>(kayak_rt::heap_cons(n, kayak_rt::nil()))
        }
    }), nset_names(s))))
}

/// The items among `names` that `e` names; in a `(with m ...)` of a
/// module item, not the names `m` gives, which are `m`'s (C88, FX-26's
/// `(define x (with m x))`). `names` a tree (C92): this walks every
/// item's body, every compile.
pub fn refs_in(e: &'static Sexp, names: &'static Nset, forms: Sexps) -> Strings {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Sym(n, f, p) => {
            if in_nset_p(n, names) {
                the::<Strings>(kayak_rt::heap_cons(n, kayak_rt::nil()))
            } else {
                nil::<Str>()
            }
        }
        Sexp::Lst(xs, f, l, p) => {
            if (head_is_p(e, str_lit("with")) && not(null_p(cdr(xs))) && {
                let tagcase_ = second(xs);
                match *tagcase_ {
                    Sexp::Sym(n, f2, p2) => {
                        true
                    }
                    _ => {
                        let other = tagcase_;
                        false
                    }
                }
            }) {
                let m = sym_name(second(xs));
                let given = concat(map(lambda1s(move |g: &'static Sexp| {
                    if (module_def_p(g) && string_eq_p(sym_name(second(items(g))), m)) {
                        concat(map(&item_names, module_written(g)))
                    } else {
                        nil::<Str>()
                    }
                }), forms));
                let inner = if null_p(given) {
                    names
                } else {
                    nset_without(names, given)
                };
                onto(if in_nset_p(m, names) {
                    the::<Strings>(kayak_rt::heap_cons(m, kayak_rt::nil()))
                } else {
                    nil::<Str>()
                }, concat(map(lambda1s(move |x: &'static Sexp| {
                    refs_in(x, inner, forms)
                }), cdr(cdr(xs)))))
            } else {
                concat(map(lambda1s(move |x: &'static Sexp| {
                    refs_in(x, names, forms)
                }), xs))
            }
        }
        _ => {
            let other = tagcase_;
            nil::<Str>()
        }
    }
}

/// What a file loaded sees (C88, FX-26's M7): the standard environment
/// alone, not the program's globals, types or effects, so that a file
/// means the same wherever it is read; the facts so far kept. And the
/// modules `sees`, which a `load-input`'s `let` bound, lifted (C116):
/// their binds, types and effects; and the shared loads' modules, whose
/// names no program writes.
pub fn standard_scope(v: &'static Cv, sees: Strings) -> &'static Cv {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, als, es, here, group, file, line, fs, tv, at) => {
            let of = lambda1s(move |n: Str| {
                (has_prefix_p(n, str_lit("made--load--")) || any_p(lambda1s(move |m: Str| {
                    (string_eq_p(n, m) || has_prefix_p(n, string_append(m, str_lit(" "))) || has_prefix_p(n, string_append(m, str_lit(".."))))
                }), sees))
            });
            let bare = cv(filter(lambda1s(move |b: &'static Bind| {
                let tagcase_ = b;
                match *tagcase_ {
                    Bind::Bind(n, sc, w) => {
                        of(n)
                    }
                }
            }), bs), filter(lambda1s(move |d: &'static Dt| {
                let tagcase_ = d;
                match *tagcase_ {
                    Dt::Dt(n, ps, vs) => {
                        of(n)
                    }
                }
            }), ds), filter(lambda1s(move |a: &'static Alias| {
                let tagcase_ = a;
                match *tagcase_ {
                    Alias::Alias(n, ps, b) => {
                        of(n)
                    }
                }
            }), als), filter(lambda1s(move |e: &'static Effdef| {
                let tagcase_ = e;
                match *tagcase_ {
                    Effdef::Effdef(n, xs) => {
                        of(n)
                    }
                }
            }), es), here, group, file, line, fs, tv, at);
            with_binds(bare, kayak_rt::heap_cons(bind(str_lit("%loaded"), scheme(nil::<Str>(), ty_unit()), str_lit("mark")), prim_binds(bare)))
        }
    }
}

/// The value items: each its form, its names, the items it names, and
/// whether it is procedures (made, not run, when its item is).
pub fn letrec_items(forms: Sexps) -> Mitems {
    let values = concat(map(lambda1s(move |f: &'static Sexp| {
        if null_p(item_value(f)) {
            nil::<&'static Sexp>()
        } else {
            the::<Sexps>(kayak_rt::heap_cons(f, kayak_rt::nil()))
        }
    }), forms));
    let names = concat(map(&item_names, values));
    map(lambda1s(move |f: &'static Sexp| {
        mitem(f, item_names(f), {
            let own = if module_def_p(f) {
                concat(map(&item_names, unhidden(module_written(f))))
            } else {
                nil::<Str>()
            };
            let set = nset_of(concat(map(lambda1s(move |n: Str| {
                if string_member_p(n, own) {
                    nil::<Str>()
                } else {
                    the::<Strings>(kayak_rt::heap_cons(n, kayak_rt::nil()))
                }
            }), names)));
            concat(map(lambda1s(move |e: &'static Sexp| {
                refs_in(e, set, forms)
            }), item_value(f)))
        }, ((head_is_p(f, str_lit("define-rec")) || head_is_p(f, str_lit("define*")) || i64_eq(size(items(f)), 4i64)) && not(any_p(lambda1s(move |e: &'static Sexp| {
            not(lambda_form_p(e))
        }), item_value(f)))))
    }), values)
}

pub enum Reached {
    Reached(Str, Strings),
}

pub fn reached(f0: Str, f1: Strings) -> &'static Reached {
    kayak_rt::heap_alloc(Reached::Reached(f0, f1))
}

pub fn reached_of(mut n: Str, mut rs: List<&'static Reached>) -> Strings {
    loop {
        if null_p(rs) {
            return nil::<Str>();
        } else if {
            let tagcase_ = car(rs);
            match *tagcase_ {
                Reached::Reached(k, ks) => {
                    string_eq_p(k, n)
                }
            }
        } {
            let tagcase_ = car(rs);
            match *tagcase_ {
                Reached::Reached(k, ks) => {
                    return ks;
                }
            }
        } else {
            rs = cdr(rs);
            continue;
        }
    }
}

// Items by name, a tree (C92).
pub enum Itree {
    Ileaf(),
    Inode(&'static Itree, Str, &'static Mitem, &'static Itree),
}

pub fn ileaf() -> &'static Itree {
    kayak_rt::heap_alloc(Itree::Ileaf())
}

pub fn inode(f0: &'static Itree, f1: Str, f2: &'static Mitem, f3: &'static Itree) -> &'static Itree {
    kayak_rt::heap_alloc(Itree::Inode(f0, f1, f2, f3))
}

pub enum NamedItem {
    NamedItem(Str, &'static Mitem),
}

pub fn named_item(f0: Str, f1: &'static Mitem) -> &'static NamedItem {
    kayak_rt::heap_alloc(NamedItem::NamedItem(f0, f1))
}

pub fn itree_built(xs: List<&'static NamedItem>, n: i64) -> &'static Itree {
    if i64_lt_eq(n, 0i64) {
        ileaf()
    } else {
        let half = i64_quotient(n, 2i64);
        let rest = named_dropped(xs, half);
        let tagcase_ = car(rest);
        match *tagcase_ {
            NamedItem::NamedItem(k, it) => {
                inode(itree_built(xs, half), k, it, itree_built(cdr(rest), i64_minus(i64_minus(n, half), 1i64)))
            }
        }
    }
}

pub fn named_dropped(mut xs: List<&'static NamedItem>, mut n: i64) -> List<&'static NamedItem> {
    loop {
        if (null_p(xs) || i64_lt_eq(n, 0i64)) {
            return xs;
        } else {
            (xs, n) = (cdr(xs), i64_minus(n, 1i64));
            continue;
        }
    }
}

pub fn named_sorted(xs: List<&'static NamedItem>) -> List<&'static NamedItem> {
    if (null_p(xs) || null_p(cdr(xs))) {
        xs
    } else {
        named_merged(named_sorted(named_halves(xs, true)), named_sorted(named_halves(xs, false)))
    }
}

pub fn named_halves(mut xs: List<&'static NamedItem>, mut first: bool) -> List<&'static NamedItem> {
    loop {
        if null_p(xs) {
            return nil::<&'static NamedItem>();
        } else if first {
            return kayak_rt::heap_cons(car(xs), named_halves(cdr(xs), false));
        } else {
            (xs, first) = (cdr(xs), true);
            continue;
        }
    }
}

pub fn named_merged(a: List<&'static NamedItem>, b: List<&'static NamedItem>) -> List<&'static NamedItem> {
    if null_p(a) {
        b
    } else if null_p(b) {
        a
    } else if {
        let tagcase_ = car(b);
        match *tagcase_ {
            NamedItem::NamedItem(kb, ib) => {
                let tagcase_ = car(a);
                match *tagcase_ {
                    NamedItem::NamedItem(ka, ia) => {
                        string_lt_p(kb, ka)
                    }
                }
            }
        }
    } {
        kayak_rt::heap_cons(car(b), named_merged(a, cdr(b)))
    } else {
        kayak_rt::heap_cons(car(a), named_merged(cdr(a), b))
    }
}

pub fn itree_of(its: Mitems) -> &'static Itree {
    let pairs = named_sorted(concat(map(lambda1s(move |it: &'static Mitem| {
        let tagcase_ = it;
        match *tagcase_ {
            Mitem::Mitem(f, ns, rs, l) => {
                map(lambda1s(move |n: Str| {
                    named_item(n, it)
                }), ns)
            }
        }
    }), its)));
    itree_built(pairs, size(pairs))
}

pub fn in_itree(mut x: Str, mut t: &'static Itree) -> Mitems {
    loop {
        let tagcase_ = t;
        match *tagcase_ {
            Itree::Ileaf() => {
                return nil::<&'static Mitem>();
            }
            Itree::Inode(l, k, it, r) => {
                if string_eq_p(x, k) {
                    return the::<Mitems>(kayak_rt::heap_cons(it, kayak_rt::nil()));
                } else if string_lt_p(x, k) {
                    t = l;
                    continue;
                } else {
                    t = r;
                    continue;
                }
            }
        }
    }
}

/// `s` with `x`, unbalanced: for what a walk has seen.
pub fn nset_added(x: Str, s: &'static Nset) -> &'static Nset {
    let tagcase_ = s;
    match *tagcase_ {
        Nset::Nempty() => {
            nnode(nempty(), x, nempty())
        }
        Nset::Nnode(l, k, r) => {
            if string_eq_p(x, k) {
                s
            } else if string_lt_p(x, k) {
                nnode(nset_added(x, l), k, r)
            } else {
                nnode(l, k, nset_added(x, r))
            }
        }
    }
}

pub fn item_of(mut n: Str, mut its: Mitems) -> Mitems {
    loop {
        if null_p(its) {
            return nil::<&'static Mitem>();
        } else if {
            let tagcase_ = car(its);
            match *tagcase_ {
                Mitem::Mitem(f, ns, rs, l) => {
                    string_member_p(n, ns)
                }
            }
        } {
            return the::<Mitems>(kayak_rt::heap_cons(car(its), kayak_rt::nil()));
        } else {
            its = cdr(its);
            continue;
        }
    }
}

/// The items `todo` reach, through every item's references, or, with
/// `through-lambdas`, only through procedures' (what making a value
/// runs); by trees, the items found and those seen (C92: by lists, it
/// had been cubic in a module's items).
pub fn reach(todo: Strings, t: &'static Itree, seen: Strings, through_lambdas: bool) -> Strings {
    reach_in(todo, t, nempty(), seen, through_lambdas)
}

pub fn reach_in(mut todo: Strings, mut t: &'static Itree, mut seen_set: &'static Nset, mut seen: Strings, mut through_lambdas: bool) -> Strings {
    loop {
        if null_p(todo) {
            return seen;
        } else if in_nset_p(car(todo), seen_set) {
            todo = cdr(todo);
            continue;
        } else {
            let it = in_itree(car(todo), t);
            (todo, seen_set, seen) = (onto(if null_p(it) {
                nil::<Str>()
            } else {
                let tagcase_ = car(it);
                match *tagcase_ {
                    Mitem::Mitem(f, ns, rs, l) => {
                        if (l || not(through_lambdas)) {
                            rs
                        } else {
                            nil::<Str>()
                        }
                    }
                }
            }, cdr(todo)), nset_added(car(todo), seen_set), kayak_rt::heap_cons(car(todo), seen));
            continue;
        }
    }
}

pub fn index_in(mut n: Str, mut ns: Strings, mut i: i64) -> i64 {
    loop {
        if null_p(ns) {
            return -1i64;
        } else if string_eq_p(car(ns), n) {
            return i;
        } else {
            (ns, i) = (cdr(ns), i64_plus(i, 1i64));
            continue;
        }
    }
}

/// FX-26's rule: a value that is no procedure is made when its item is,
/// so every item it reaches through procedures must be made before it.
pub fn made_before(v: &'static Cv, its: Mitems, t: &'static Itree) -> () {
    let order = concat(map(lambda1s(move |it: &'static Mitem| {
        let tagcase_ = it;
        match *tagcase_ {
            Mitem::Mitem(f, ns, rs, l) => {
                ns
            }
        }
    }), its));
    map(lambda1s(move |it: &'static Mitem| {
        let tagcase_ = it;
        match *tagcase_ {
            Mitem::Mitem(f, ns, rs, l) => {
                if l {
                    ()
                } else {
                    let late = concat(map(lambda1s(move |n: Str| {
                        if i64_gt_eq(index_in(n, order, 0i64), index_in(car(ns), order, 0i64)) {
                            the::<Strings>(kayak_rt::heap_cons(n, kayak_rt::nil()))
                        } else {
                            nil::<Str>()
                        }
                    }), reach(rs, t, nil::<Str>(), true)));
                    if null_p(late) {
                        ()
                    } else {
                        match refuse(v, string_append(car(ns), string_append(str_lit(" is made from "), string_append(car(late), str_lit(", which is not made before it: a module's value sees only the items made before it, as FX-26's letrec* has it"))))) {}
                    }
                }
            }
        }
    }), its);
    ()
}

/// The items, as sets that reach one another, each set after those it
/// reaches: the order they are checked in. `rs`, what each reaches,
/// found once (C92: found here again for each pair, it had cost a
/// module of 160 items a tenth of a second).
pub fn components(todo: Mitems, its: Mitems, rs: List<&'static Reached>) -> List<Mitems> {
    if null_p(todo) {
        nil::<List<&'static Mitem>>()
    } else {
        let it = car(todo);
        let n = {
            let tagcase_ = it;
            match *tagcase_ {
                Mitem::Mitem(f, ns, rs2, l) => {
                    car(ns)
                }
            }
        };
        let mine = reached_of(n, rs);
        let same = concat(map(lambda1s(move |x: &'static Mitem| {
            let tagcase_ = x;
            match *tagcase_ {
                Mitem::Mitem(f, ns, rs2, l) => {
                    if (string_member_p(car(ns), mine) && string_member_p(n, reached_of(car(ns), rs))) {
                        the::<Mitems>(kayak_rt::heap_cons(x, kayak_rt::nil()))
                    } else {
                        nil::<&'static Mitem>()
                    }
                }
            }
        }), its));
        let rest = concat(map(lambda1s(move |x: &'static Mitem| {
            let tagcase_ = x;
            match *tagcase_ {
                Mitem::Mitem(f, ns, rs2, l) => {
                    if any_p(lambda1s(move |y: &'static Mitem| {
                        let tagcase_ = y;
                        match *tagcase_ {
                            Mitem::Mitem(g, ms, qs, k) => {
                                string_eq_p(car(ms), car(ns))
                            }
                        }
                    }), same) {
                        nil::<&'static Mitem>()
                    } else {
                        the::<Mitems>(kayak_rt::heap_cons(x, kayak_rt::nil()))
                    }
                }
            }
        }), todo));
        let deps = concat(map(lambda1s(move |x: &'static Mitem| {
            let tagcase_ = x;
            match *tagcase_ {
                Mitem::Mitem(f, ns, rs2, l) => {
                    if (string_member_p(car(ns), mine) && not(any_p(lambda1s(move |y: &'static Mitem| {
                        let tagcase_ = y;
                        match *tagcase_ {
                            Mitem::Mitem(g, ms, qs, k) => {
                                string_eq_p(car(ms), car(ns))
                            }
                        }
                    }), same))) {
                        the::<Mitems>(kayak_rt::heap_cons(x, kayak_rt::nil()))
                    } else {
                        nil::<&'static Mitem>()
                    }
                }
            }
        }), rest));
        let later = concat(map(lambda1s(move |x: &'static Mitem| {
            if any_p(lambda1s(move |y: &'static Mitem| {
                let tagcase_ = y;
                match *tagcase_ {
                    Mitem::Mitem(g, ms, qs, k) => {
                        let tagcase_ = x;
                        match *tagcase_ {
                            Mitem::Mitem(f, ns, rs2, l) => {
                                string_eq_p(car(ms), car(ns))
                            }
                        }
                    }
                }
            }), deps) {
                nil::<&'static Mitem>()
            } else {
                the::<Mitems>(kayak_rt::heap_cons(x, kayak_rt::nil()))
            }
        }), rest));
        onto(components(deps, its, rs), kayak_rt::heap_cons(same, components(later, its, rs)))
    }
}

/// Items that reach one another, as one `define-rec` of their procedures,
/// each where its item is (incr.kfx keys the group by their texts).
pub fn rec_of(members: Sexps) -> Sexps {
    let tagcase_ = car(members);
    match *tagcase_ {
        Sexp::Lst(xs, file, line, pos) => {
            the::<Sexps>(kayak_rt::heap_cons(lst(kayak_rt::heap_cons(sym(str_lit("define-rec"), file, pos), concat(map(lambda1s(move |g: &'static Sexp| {
                if head_is_p(g, str_lit("define-rec")) {
                    cdr(items(g))
                } else {
                    let ys = items(g);
                    the::<Sexps>(kayak_rt::heap_cons(lst(kayak_rt::heap_cons(second(ys), kayak_rt::heap_cons(third(ys), kayak_rt::heap_cons(car(item_value(g)), kayak_rt::nil()))), datum_file(g), line, datum_pos(g)), kayak_rt::nil()))
                }
            }), members))), file, line, pos), kayak_rt::nil()))
        }
        _ => {
            let other = tagcase_;
            nil::<&'static Sexp>()
        }
    }
}

/// Whether a set of items is checked as written: one, reaching not itself.
pub fn alone_p(group: Mitems) -> bool {
    (null_p(cdr(group)) && {
        let tagcase_ = car(group);
        match *tagcase_ {
            Mitem::Mitem(f, ns, rs, l) => {
                (not(l) || head_is_p(f, str_lit("define-rec")) || head_is_p(f, str_lit("define*")) || not(any_p(lambda1s(move |r: Str| {
                    string_member_p(r, ns)
                }), rs)))
            }
        }
    })
}

/// A set of items to check: one alone, as written, unless it reaches
/// itself; else one `define-rec` of their procedures.
pub fn as_group(v: &'static Cv, group: Mitems) -> Sexps {
    if alone_p(group) {
        the::<Sexps>(kayak_rt::heap_cons({
            let tagcase_ = car(group);
            match *tagcase_ {
                Mitem::Mitem(f, ns, rs, l) => {
                    f
                }
            }
        }, kayak_rt::nil()))
    } else if any_p(lambda1s(move |it: &'static Mitem| {
        let tagcase_ = it;
        match *tagcase_ {
            Mitem::Mitem(f, ns, rs, l) => {
                (not(l) || head_is_p(f, str_lit("define*")))
            }
        }
    }), group) {
        match refuse(v, string_append(str_lit("items that reach one another, not each a typed lambda: "), words_of(concat(map(lambda1s(move |it: &'static Mitem| {
            let tagcase_ = it;
            match *tagcase_ {
                Mitem::Mitem(f, ns, rs, l) => {
                    ns
                }
            }
        }), group))))) {}
    } else {
        rec_of(map(lambda1s(move |it: &'static Mitem| {
            let tagcase_ = it;
            match *tagcase_ {
                Mitem::Mitem(f, ns, rs, l) => {
                    f
                }
            }
        }), group))
    }
}

// A module's order, and its code (C92): `(s P)` for an item checked as
// written, `(r P ...)` for items checked as one `define-rec`, `P` where
// each is, from where the module's first item is (an edit before the
// module moves every item, and the order with them); which incr.kfx keeps,
// so that an unchanged module's order is not found again, its every body
// walked.
pub fn least_position(mut forms: Sexps, mut least: i64) -> i64 {
    loop {
        if null_p(forms) {
            return least;
        } else if (i64_gt(datum_pos(car(forms)), 0i64) && (i64_lt(least, 0i64) || i64_lt(datum_pos(car(forms)), least))) {
            (forms, least) = (cdr(forms), datum_pos(car(forms)));
            continue;
        } else {
            forms = cdr(forms);
            continue;
        }
    }
}

pub fn first_position(forms: Sexps) -> i64 {
    least_position(forms, -1i64)
}

pub enum Ordered {
    Ordered(Sexps, Str),
}

pub fn ordered(f0: Sexps, f1: Str) -> &'static Ordered {
    kayak_rt::heap_alloc(Ordered::Ordered(f0, f1))
}

/// A module's types and modules, as written, checked before its values.
pub fn first_checked(forms: Sexps) -> Sexps {
    concat(map(lambda1s(move |f: &'static Sexp| {
        if (null_p(item_value(f)) || module_def_p(f)) {
            the::<Sexps>(kayak_rt::heap_cons(f, kayak_rt::nil()))
        } else {
            nil::<&'static Sexp>()
        }
    }), forms))
}

/// A module's items in the order KFX checks them: its types and modules
/// as written (a type may select a module's), then its values, each after
/// what it reaches, those that reach one another as one group. A module
/// item is made where it is written all the same (C88).
pub fn module_order_coded(v: &'static Cv, forms: Sexps) -> &'static Ordered {
    let its = letrec_items(forms);
    let t = itree_of(its);
    let values = concat(map(lambda1s(move |it: &'static Mitem| {
        let tagcase_ = it;
        match *tagcase_ {
            Mitem::Mitem(f, ns, rs, l) => {
                if module_def_p(f) {
                    nil::<&'static Mitem>()
                } else {
                    the::<Mitems>(kayak_rt::heap_cons(it, kayak_rt::nil()))
                }
            }
        }
    }), its));
    let groups = {
        made_before(v, its, t);
        components(values, its, map(lambda1s(move |it: &'static Mitem| {
            let tagcase_ = it;
            match *tagcase_ {
                Mitem::Mitem(f, ns, rs, l) => {
                    reached(car(ns), reach(kayak_rt::heap_cons(car(ns), kayak_rt::nil()), t, nil::<Str>(), false))
                }
            }
        }), its))
    };
    ordered(onto(first_checked(forms), concat(map(lambda1s(move |g: Mitems| {
        as_group(v, g)
    }), groups))), words_of(map(lambda1s(move |g: Mitems| {
        string_append(if alone_p(g) {
            str_lit("(s ")
        } else {
            str_lit("(r ")
        }, string_append(words_of(map(lambda1s(move |it: &'static Mitem| {
            let tagcase_ = it;
            match *tagcase_ {
                Mitem::Mitem(f, ns, rs, l) => {
                    i64_to_string(i64_minus(datum_pos(f), first_position(forms)))
                }
            }
        }), g)), str_lit(")")))
    }), groups)))
}

pub fn module_order(v: &'static Cv, forms: Sexps) -> Sexps {
    let tagcase_ = module_order_coded(v, forms);
    match *tagcase_ {
        Ordered::Ordered(fs, code) => {
            fs
        }
    }
}

pub fn form_at(mut p: i64, mut forms: Sexps) -> Sexps {
    loop {
        if null_p(forms) {
            return nil::<&'static Sexp>();
        } else if i64_eq(datum_pos(car(forms)), p) {
            return the::<Sexps>(kayak_rt::heap_cons(car(forms), kayak_rt::nil()));
        } else {
            forms = cdr(forms);
            continue;
        }
    }
}

/// An order kept (`module-order-coded`'s code), made again.
pub fn order_from_code(forms: Sexps, code: Str) -> Sexps {
    onto(first_checked(forms), concat(map(lambda1s(move |g: &'static Sexp| {
        let members = concat(map(lambda1s(move |p: &'static Sexp| {
            form_at({
                let tagcase_ = p;
                match *tagcase_ {
                    Sexp::Num(k, f, q) => {
                        i64_plus(k, first_position(forms))
                    }
                    _ => {
                        let other = tagcase_;
                        -1i64
                    }
                }
            }, forms)
        }), cdr(items(g))));
        if head_is_p(g, str_lit("s")) {
            members
        } else {
            rec_of(members)
        }
    }), read_all(string_chars(code), str_lit(""), 1i64))))
}

// A module checked (C91): its scope made (`module-prep`), its items checked
// in order, and what it gives the forms after it (`module-finish`); split so
// that incr.kfx checks the items with memos, between the two.
pub enum Mprep {
    Mprep(&'static Cv, &'static Cv, &'static Cv, Str, &'static Bind, Sexps, bool, Sexps, Strings, Strings, Strings, Binds),
}

pub fn mprep(f0: &'static Cv, f1: &'static Cv, f2: &'static Cv, f3: Str, f4: &'static Bind, f5: Sexps, f6: bool, f7: Sexps, f8: Strings, f9: Strings, f10: Strings, f11: Binds) -> &'static Mprep {
    kayak_rt::heap_alloc(Mprep::Mprep(f0, f1, f2, f3, f4, f5, f6, f7, f8, f9, f10, f11))
}

pub fn prep_inner(p: &'static Mprep) -> &'static Cv {
    let tagcase_ = p;
    match *tagcase_ {
        Mprep::Mprep(outer, v, inner, m, made, written, loaded, forms, hidden, hidden_types, names, conversions) => {
            inner
        }
    }
}

pub fn prep_name(p: &'static Mprep) -> Str {
    let tagcase_ = p;
    match *tagcase_ {
        Mprep::Mprep(outer, v, inner, m, made, written, loaded, forms, hidden, hidden_types, names, conversions) => {
            m
        }
    }
}

pub fn prep_forms(p: &'static Mprep) -> Sexps {
    let tagcase_ = p;
    match *tagcase_ {
        Mprep::Mprep(outer, v, inner, m, made, written, loaded, forms, hidden, hidden_types, names, conversions) => {
            forms
        }
    }
}

/// A module's `define-effect`s, each defined in turn, as its items will be.
pub fn own_effects(mut v: &'static Cv, mut forms: Sexps) -> &'static Cv {
    loop {
        if null_p(forms) {
            return v;
        } else if (head_is_p(car(forms), str_lit("define-effect")) && not(selects_p(car(forms)))) {
            (v, forms) = ({
                let tagcase_ = car(forms);
                match *tagcase_ {
                    Sexp::Lst(xs, f, l, p) => {
                        with_effdef(near(v, f, l, p), xs)
                    }
                    _ => {
                        let other = tagcase_;
                        v
                    }
                }
            }, cdr(forms));
            continue;
        } else {
            forms = cdr(forms);
            continue;
        }
    }
}

pub fn module_prep(v: &'static Cv, form: &'static Sexp) -> &'static Mprep {
    let xs = items(form);
    let m = name_of(v, second(xs));
    let v = at(v, m, nil::<Str>());
    let v = if string_member_p(mangle(m), kayak_rt::heap_cons(str_lit("kayak_rt"), kayak_rt::heap_cons(str_lit("std"), kayak_rt::heap_cons(str_lit("core"), kayak_rt::heap_cons(str_lit("alloc"), kayak_rt::nil()))))) {
        match refuse(v, string_append(str_lit("a module named as a Rust crate the program sees: "), m)) {}
    } else {
        v
    };
    let made = {
        let tagcase_ = global(v, m, scheme(nil::<Str>(), ty_unit()));
        match *tagcase_ {
            Bind::Bind(n, sc, wher) => {
                bind(n, sc, str_lit("module"))
            }
        }
    };
    let written = module_written(form);
    let loaded = (not(null_p(written)) && head_is_p(car(written), str_lit("%loaded")));
    let outer = v;
    let v = if loaded {
        standard_scope(v, map(&sym_name, cdr(cdr(items(car(written))))))
    } else {
        v
    };
    let forms = unhidden(written);
    let escapes = hidden_escapes(v, written);
    let hidden_types = hidden_type_names(written);
    let all_includes = onto(included(v, forms), included(v, concat(map(lambda1s(move |f: &'static Sexp| {
        if head_is_p(f, str_lit("hide")) {
            cdr(items(f))
        } else {
            nil::<&'static Sexp>()
        }
    }), written))));
    let include_binds = map(lambda1s(move |n: Str| {
        typed_binds(n, excepted_binds(v, written, n, cv_binds(v)))
    }), all_includes);
    let hidden = onto(hidden_value_names(written), map(lambda1s(move |b: &'static Bind| {
        let tagcase_ = b;
        match *tagcase_ {
            Bind::Bind(n, sc, w) => {
                n
            }
        }
    }), concat(map(lambda1s(move |n: Str| {
        binds_of_include(n, include_binds)
    }), included(v, concat(map(lambda1s(move |f: &'static Sexp| {
        if head_is_p(f, str_lit("hide")) {
            cdr(items(f))
        } else {
            nil::<&'static Sexp>()
        }
    }), written)))))));
    let includes = included(v, forms);
    let names = module_types(v, forms);
    let given_values = onto(concat(map(&item_value_names, forms)), concat(map(lambda1s(move |b: &'static Bind| {
        let tagcase_ = b;
        match *tagcase_ {
            Bind::Bind(n, sc, w) => {
                if has_prefix_p(n, str_lit("%")) {
                    nil::<Str>()
                } else {
                    the::<Strings>(kayak_rt::heap_cons(n, kayak_rt::nil()))
                }
            }
        }
    }), concat(map(lambda1s(move |n: Str| {
        binds_of_include(n, include_binds)
    }), includes)))));
    let given_types = concat(map(&item_type_names, forms));
    let included_aliases = map(lambda1s(move |a: &'static Alias| {
        let tagcase_ = a;
        match *tagcase_ {
            Alias::Alias(n, ps, body) => {
                alias(n, ps, resolved_alias(body, cv_aliases(v)))
            }
        }
    }), concat(map(lambda1s(move |n: Str| {
        excepted_aliases(v, written, n, cv_aliases(v))
    }), includes)));
    let v = if (repeated_p(given_values) || repeated_p(onto(given_types, map(lambda1s(move |a: &'static Alias| {
        let tagcase_ = a;
        match *tagcase_ {
            Alias::Alias(n, ps, b) => {
                n
            }
        }
    }), distinct_aliases(included_aliases))))) {
        match refuse(v, str_lit("a name defined twice in this module, its own or included")) {}
    } else {
        v
    };
    let typed = {
        let tagcase_ = v;
        match *tagcase_ {
            Cv::Cv(bs, ds, als, es, here, group, file, line, fs, tv, at) => {
                cv(bind_onto(concat(map(lambda1s(move |n: Str| {
                    binds_of_include(n, include_binds)
                }), includes)), kayak_rt::heap_cons(bind(str_lit("%module"), scheme(nil::<Str>(), ty_unit()), m), bs)), onto(module_dts(v, m, forms), ds), onto(module_aliases(v, m, names, forms, true), onto(concat(map(lambda1s(move |n: Str| {
                    excepted_aliases(v, written, n, als)
                }), includes)), als)), onto(concat(map(lambda1s(move |n: Str| {
                    opened_effdefs(n, es)
                }), includes)), es), here, group, file, line, fs, tv, at)
            }
        }
    };
    let typed = own_effects(typed, forms);
    let datatypes = module_datatypes(typed, m, forms);
    let typed = {
        let tagcase_ = typed;
        match *tagcase_ {
            Cv::Cv(bs, ds, als, es, here, group, file, line, fs, tv, at) => {
                cv(bs, onto(datatypes, ds), als, es, here, group, file, line, fs, tv, at)
            }
        }
    };
    let conversions = module_conversions(typed, m, forms);
    let inner = defined_once(typed, onto(conversions, concat(map(&constructors, datatypes))));
    mprep(outer, v, inner, m, made, written, loaded, forms, hidden, hidden_types, names, conversions)
}

pub fn module_finish(p: &'static Mprep, checked: &'static Elab) -> &'static Elab {
    let tagcase_ = p;
    match *tagcase_ {
        Mprep::Mprep(outer, v, inner, m, made, written, loaded, forms, hidden, hidden_types, names, conversions) => {
            let tagcase_ = checked;
            match *tagcase_ {
                Elab::Elab(done, found) => {
                    let tagcase_ = done;
                    match *tagcase_ {
                        Cv::Cv(bs, ds, als, es, here, group, file, line, fs, tv, at) => {
                            elab(cv(kayak_rt::heap_cons(made, bind_onto(module_exports(m, onto(hidden, map(lambda1s(move |b: &'static Bind| {
                                let tagcase_ = b;
                                match *tagcase_ {
                                    Bind::Bind(n, sc, w) => {
                                        n
                                    }
                                }
                            }), conversions)), bs), cv_binds(outer))), if loaded {
                                onto(ds, cv_dts(outer))
                            } else {
                                ds
                            }, onto(without_aliases(hidden_types, m, module_aliases(v, m, names, forms, false)), onto(concat(map(lambda1s(move |n: Str| {
                                renamed_aliases(n, m, excepted_aliases(v, written, n, als))
                            }), unhidden_includes(v, written))), cv_aliases(outer))), onto(module_effects(m, forms, es), onto(concat(map(lambda1s(move |n: Str| {
                                map(lambda1s(move |d: &'static Effdef| {
                                    let tagcase_ = d;
                                    match *tagcase_ {
                                        Effdef::Effdef(k, atoms) => {
                                            effdef(string_append(m, string_append(str_lit(" "), k)), atoms)
                                        }
                                    }
                                }), opened_effdefs(n, es))
                            }), unhidden_includes(v, written))), cv_effdefs(outer))), here, group, file, line, fs, tv, at), found)
                        }
                    }
                }
            }
        }
    }
}

/// One of a module's items: as a program's form, but that its generative
/// types are made already, and its elaborated types are named `m x`.
pub fn check_item(v: &'static Cv, m: Str, form: &'static Sexp) -> &'static Elab {
    if (head_is_p(form, str_lit("define-generative")) || head_is_p(form, str_lit("define-datatype")) || head_is_p(form, str_lit("include")) || head_is_p(form, str_lit("%loaded"))) {
        elab(v, nil::<&'static Typed>())
    } else if module_def_p(form) {
        // A module in a module (C88): checked as one, its names the outer's
        // items, `n x` for its `x`, which the outer gives on as `m n x`.
        let tagcase_ = form;
        match *tagcase_ {
            Sexp::Lst(xs, src_file, src_line, src_pos) => {
                let tagcase_ = check_module(near(v, src_file, src_line, src_pos), form);
                match *tagcase_ {
                    Elab::Elab(v2, more) => {
                        elab(at(v2, str_lit(""), nil::<Str>()), nil::<&'static Typed>())
                    }
                }
            }
            _ => {
                let other = tagcase_;
                elab(v, nil::<&'static Typed>())
            }
        }
    } else if untyped_p(form) {
        let tagcase_ = form;
        match *tagcase_ {
            Sexp::Lst(xs, src_file, src_line, src_pos) => {
                let tagcase_ = check_untyped(near(v, src_file, src_line, src_pos), form);
                match *tagcase_ {
                    Elab::Elab(v2, more) => {
                        elab(at(v2, str_lit(""), nil::<Str>()), map(lambda1s(move |x: &'static Typed| {
                            let tagcase_ = x;
                            match *tagcase_ {
                                Typed::Typed(n, t) => {
                                    typed(string_append(m, string_append(str_lit(" "), n)), t)
                                }
                            }
                        }), more))
                    }
                }
            }
            _ => {
                let other = tagcase_;
                elab(v, nil::<&'static Typed>())
            }
        }
    } else {
        elab(check_top(v, form), nil::<&'static Typed>())
    }
}

/// A module's items, in order.
pub fn check_items(mut v: &'static Cv, mut m: Str, mut forms: Sexps, mut found: Typeds) -> &'static Elab {
    loop {
        if null_p(forms) {
            return elab(v, found);
        } else {
            let tagcase_ = check_item(v, m, car(forms));
            match *tagcase_ {
                Elab::Elab(v2, more) => {
                    (v, forms, found) = (v2, cdr(forms), onto(more, found));
                    continue;
                }
            }
        }
    }
}

pub fn check_module(v: &'static Cv, form: &'static Sexp) -> &'static Elab {
    let p = module_prep(v, form);
    module_finish(p, check_items(prep_inner(p), prep_name(p), module_order(prep_inner(p), prep_forms(p)), nil::<&'static Typed>()))
}

/// The forms in order; `found`, the types elaborated so far.
pub fn check_tops(mut v: &'static Cv, mut forms: Sexps, mut found: Typeds) -> &'static Elab {
    loop {
        if null_p(forms) {
            return elab(v, found);
        } else if module_def_p(car(forms)) {
            let tagcase_ = car(forms);
            match *tagcase_ {
                Sexp::Lst(xs, src_file, src_line, src_pos) => {
                    let tagcase_ = check_module(near(v, src_file, src_line, src_pos), car(forms));
                    match *tagcase_ {
                        Elab::Elab(v2, more) => {
                            (v, forms, found) = (at(v2, str_lit(""), nil::<Str>()), cdr(forms), onto(more, found));
                            continue;
                        }
                    }
                }
                _ => {
                    let other = tagcase_;
                    forms = cdr(forms);
                    continue;
                }
            }
        } else if untyped_p(car(forms)) {
            let tagcase_ = car(forms);
            match *tagcase_ {
                Sexp::Lst(xs, src_file, src_line, src_pos) => {
                    let tagcase_ = check_untyped(near(v, src_file, src_line, src_pos), car(forms));
                    match *tagcase_ {
                        Elab::Elab(v2, more) => {
                            (v, forms, found) = (at(v2, str_lit(""), nil::<Str>()), cdr(forms), onto(more, found));
                            continue;
                        }
                    }
                }
                _ => {
                    let other = tagcase_;
                    forms = cdr(forms);
                    continue;
                }
            }
        } else {
            (v, forms) = (check_top(v, car(forms)), cdr(forms));
            continue;
        }
    }
}

// What checking a program gives the emitter: the types of the definitions
// written with none, and the facts.
pub enum Verdict {
    Verdict(Typeds, Facts),
}

pub fn verdict(f0: Typeds, f1: Facts) -> &'static Verdict {
    kayak_rt::heap_alloc(Verdict::Verdict(f0, f1))
}

pub fn verdict_typeds(x: &'static Verdict) -> Typeds {
    let tagcase_ = x;
    match *tagcase_ {
        Verdict::Verdict(ts, fs) => {
            ts
        }
    }
}

pub fn verdict_facts(x: &'static Verdict) -> Facts {
    let tagcase_ = x;
    match *tagcase_ {
        Verdict::Verdict(ts, fs) => {
            fs
        }
    }
}

/// Every form, in order; the first error stops the compiler. What it gives
/// is the types of the definitions written with none.
pub fn check_program(forms: Sexps) -> &'static Verdict {
    let empty = cv(nil::<&'static Bind>(), nil::<&'static Dt>(), nil::<&'static Alias>(), nil::<&'static Effdef>(), str_lit("a type"), nil::<Str>(), str_lit("the program"), 0i64, nil::<&'static Fact>(), nil::<Str>(), 0i64);
    let start = cv(nil::<&'static Bind>(), nil::<&'static Dt>(), declare_types(empty, forms, nil::<&'static Alias>()), nil::<&'static Effdef>(), str_lit("a type"), nil::<Str>(), str_lit("the program"), 0i64, nil::<&'static Fact>(), nil::<Str>(), 0i64);
    let types = type_names_free(start, forms);
    let named = {
        let tagcase_ = start;
        match *tagcase_ {
            Cv::Cv(bs, ds, als, es, here, group, file, line, fs, tv, at) => {
                cv(bs, datatype_names(start, forms, nil::<&'static Dt>()), als, es, here, group, file, line, fs, tv, at)
            }
        }
    };
    let typed = {
        let tagcase_ = named;
        match *tagcase_ {
            Cv::Cv(bs, ds, als, es, here, group, file, line, fs, tv, at) => {
                cv(bs, declare_datatypes(named, forms, nil::<&'static Dt>()), als, es, here, group, file, line, fs, tv, at)
            }
        }
    };
    let v = with_binds(typed, prim_binds(typed));
    let tagcase_ = check_tops(v, forms, nil::<&'static Typed>());
    match *tagcase_ {
        Elab::Elab(done, found) => {
            verdict(found, cv_facts(done))
        }
    }
}

// A file read, for a load: its path and text (C88).
pub enum Filed {
    Filed(Str, Str),
}

pub fn filed(f0: Str, f1: Str) -> &'static Filed {
    kayak_rt::heap_alloc(Filed::Filed(f0, f1))
}

pub type Fileds = List<&'static Filed>;

/// `cs`'s characters before its last `c`, newest first, onto nothing if
/// it has none: `seen` the characters since the last `c` so far, newest
/// first, `before` those before it.
pub fn before_last(mut cs: Chars, mut c: char, mut seen: Chars, mut before: Chars) -> Chars {
    loop {
        if null_p(cs) {
            return before;
        } else if char_eq_p(car(cs), c) {
            (cs, seen, before) = (cdr(cs), nil::<char>(), kayak_rt::heap_cons(c, onto(seen, before)));
            continue;
        } else {
            (cs, seen) = (cdr(cs), kayak_rt::heap_cons(car(cs), seen));
            continue;
        }
    }
}

/// `cs`'s characters after its last `c`, or all of them, newest first.
pub fn after_last(mut cs: Chars, mut c: char, mut acc: Chars) -> Chars {
    loop {
        if null_p(cs) {
            return acc;
        } else if char_eq_p(car(cs), c) {
            (cs, acc) = (cdr(cs), nil::<char>());
            continue;
        } else {
            (cs, acc) = (cdr(cs), kayak_rt::heap_cons(car(cs), acc));
            continue;
        }
    }
}

/// Where `path` is: before its last `/`, without it; `` for a name alone.
pub fn directory_of(path: Str) -> Str {
    let before = before_last(string_chars(path), '/', nil::<char>(), nil::<char>());
    if null_p(before) {
        str_lit("")
    } else {
        rev_to_string(cdr(before))
    }
}

/// A file's name, without where it is or its extension.
pub fn stem(path: Str) -> Str {
    let name = rev_to_string(after_last(string_chars(path), '/', nil::<char>()));
    let before = before_last(string_chars(name), '.', nil::<char>(), nil::<char>());
    if (null_p(before) || null_p(cdr(before))) {
        name
    } else {
        rev_to_string(cdr(before))
    }
}

/// Whether `path` names a module Fixpt builds in, `fx26:NAME` (C107).
pub fn built_in_path_p(path: Str) -> bool {
    has_prefix_p(path, str_lit("fx26:"))
}

pub fn path_joined(dir: Str, name: Str) -> Str {
    if string_eq_p(dir, str_lit("")) {
        name
    } else {
        string_append(dir, string_append(str_lit("/"), name))
    }
}

// A `load-module` of a path (C88, FX-26's M7): a file's forms as a
// module's items, the path from the loading file's directory. The driver
// reads the files (`loads-read`); here each load is the module whose first
// item is `%loaded` and its path, which the checker checks in the standard
// environment alone, as FX-26 reads a file.
pub fn load_paths(e: &'static Sexp, dir: Str) -> Strings {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Lst(xs, f, l, p) => {
            if ((head_is_p(e, str_lit("load-module")) || head_is_p(e, str_lit("load-input"))) && i64_eq(size(xs), 2i64) && {
                let tagcase_ = second(xs);
                match *tagcase_ {
                    Sexp::Str(s, f2, p2) => {
                        true
                    }
                    _ => {
                        let other = tagcase_;
                        false
                    }
                }
            }) {
                let tagcase_ = second(xs);
                match *tagcase_ {
                    Sexp::Str(s, f2, p2) => {
                        if built_in_path_p(s) {
                            nil::<Str>()
                        } else {
                            the::<Strings>(kayak_rt::heap_cons(path_joined(dir, s), kayak_rt::nil()))
                        }
                    }
                    _ => {
                        let other = tagcase_;
                        nil::<Str>()
                    }
                }
            } else {
                concat(map(lambda1s(move |x: &'static Sexp| {
                    load_paths(x, dir)
                }), xs))
            }
        }
        _ => {
            let other = tagcase_;
            nil::<Str>()
        }
    }
}

/// Whether `e` has a `load-module` in it: of a module built in, perhaps,
/// which no file is read for (C107).
pub fn loads_p(e: &'static Sexp) -> bool {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Lst(xs, f, l, p) => {
            (head_is_p(e, str_lit("load-module")) || head_is_p(e, str_lit("load-input")) || any_p(&loads_p, xs))
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

pub fn load_paths_all(forms: Sexps, dir: Str) -> Strings {
    concat(map(lambda1s(move |f: &'static Sexp| {
        load_paths(f, dir)
    }), forms))
}

pub fn renamed(e: &'static Sexp, from: Str, to: Str) -> &'static Sexp {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Sym(n, f, p) => {
            if string_eq_p(n, from) {
                sym(to, f, p)
            } else {
                e
            }
        }
        Sexp::Lst(xs, f, l, p) => {
            lst(map(lambda1s(move |x: &'static Sexp| {
                renamed(x, from, to)
            }), xs), f, l, p)
        }
        _ => {
            let other = tagcase_;
            e
        }
    }
}

pub fn renamed_all(mut es: Sexps, mut froms: Strings, mut tos: Strings) -> Sexps {
    loop {
        if null_p(froms) {
            return es;
        } else {
            (es, froms, tos) = (map(lambda1s(move |e: &'static Sexp| {
                renamed(e, car(froms), car(tos))
            }), es), cdr(froms), cdr(tos));
            continue;
        }
    }
}

// A load's module, shared (C116): FX-26 makes a path once, one value for
// all its loads (and a file of `module-parameters` once for each call), so
// its datatypes are one; KFX's are Rust enums, one for each module, so a
// path, with what it is given, is one module, `made--load--K`, defined at
// the top level before the form that first loads it, which each load
// includes. `keyed`: a path and its arguments, written, and its module's
// name; `spliced-to`: a form spliced, the modules it defined first, and
// every path's so far.
pub enum Keyed {
    Keyed(Str, Str),
}

pub fn keyed(f0: Str, f1: Str) -> &'static Keyed {
    kayak_rt::heap_alloc(Keyed::Keyed(f0, f1))
}

pub type Keyeds = List<&'static Keyed>;

pub enum SplicedTo {
    SplicedTo(&'static Sexp, Sexps, Keyeds),
}

pub fn spliced_to(f0: &'static Sexp, f1: Sexps, f2: Keyeds) -> &'static SplicedTo {
    kayak_rt::heap_alloc(SplicedTo::SplicedTo(f0, f1, f2))
}

/// What `e` loads: `(load-module "p")`, as a list of its path and no
/// arguments; `((proj (load-module "p") r ...))`, of its path and its
/// regions (a file of `module-parameters`); else nothing.
pub fn load_of(e: &'static Sexp) -> Sexps {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Lst(xs, f, l, p) => {
            if (head_is_p(e, str_lit("load-module")) && i64_eq(size(xs), 2i64) && {
                let tagcase_ = second(xs);
                match *tagcase_ {
                    Sexp::Str(s, f2, p2) => {
                        true
                    }
                    _ => {
                        let other = tagcase_;
                        false
                    }
                }
            }) {
                kayak_rt::heap_cons(second(xs), kayak_rt::nil())
            } else if (i64_eq(size(xs), 1i64) && head_is_p(car(xs), str_lit("proj")) && i64_gt(size(items(car(xs))), 1i64) && {
                let tagcase_ = second(items(car(xs)));
                match *tagcase_ {
                    Sexp::Lst(ys, f2, l2, p2) => {
                        (head_is_p(second(items(car(xs))), str_lit("load-module")) && i64_eq(size(ys), 2i64) && {
                            let tagcase_ = second(ys);
                            match *tagcase_ {
                                Sexp::Str(s, f3, p3) => {
                                    true
                                }
                                _ => {
                                    let other = tagcase_;
                                    false
                                }
                            }
                        })
                    }
                    _ => {
                        let other = tagcase_;
                        false
                    }
                }
            }) {
                kayak_rt::heap_cons(second(items(second(items(car(xs))))), cdr(cdr(items(car(xs)))))
            } else {
                nil::<&'static Sexp>()
            }
        }
        _ => {
            let other = tagcase_;
            nil::<&'static Sexp>()
        }
    }
}

pub fn spliced_form(s: &'static SplicedTo) -> &'static Sexp {
    let tagcase_ = s;
    match *tagcase_ {
        SplicedTo::SplicedTo(x, d, k) => {
            x
        }
    }
}

pub fn spliced_defs(s: &'static SplicedTo) -> Sexps {
    let tagcase_ = s;
    match *tagcase_ {
        SplicedTo::SplicedTo(x, d, k) => {
            d
        }
    }
}

pub fn spliced_known(s: &'static SplicedTo) -> Keyeds {
    let tagcase_ = s;
    match *tagcase_ {
        SplicedTo::SplicedTo(x, d, k) => {
            k
        }
    }
}

/// A load of a module already made: a module that includes it.
pub fn included_module(name: Str, f: Str, l: i64, p: i64) -> &'static Sexp {
    lst(kayak_rt::heap_cons(sym(str_lit("module"), f, p), kayak_rt::heap_cons(lst(kayak_rt::heap_cons(sym(str_lit("include"), f, p), kayak_rt::heap_cons(sym(name, f, p), kayak_rt::nil())), f, l, p), kayak_rt::nil())), f, l, p)
}

/// Among a form's items, perhaps hidden, each `(define m L)` whose `L`
/// was a load, now a module including the shared one: `m` and that
/// module's name.
pub fn shared_names(its: Sexps) -> Keyeds {
    concat(map(lambda1s(move |g: &'static Sexp| {
        if (head_is_p(g, str_lit("define")) && i64_eq(size(items(g)), 3i64) && head_is_p(third(items(g)), str_lit("module")) && i64_eq(size(items(third(items(g)))), 2i64) && head_is_p(second(items(third(items(g)))), str_lit("include"))) {
            let tagcase_ = second(items(second(items(third(items(g))))));
            match *tagcase_ {
                Sexp::Sym(n, f, p) => {
                    if has_prefix_p(n, str_lit("made--load--")) {
                        the::<Keyeds>(kayak_rt::heap_cons(keyed({
                            let tagcase_ = second(items(g));
                            match *tagcase_ {
                                Sexp::Sym(m, f2, p2) => {
                                    m
                                }
                                _ => {
                                    let other = tagcase_;
                                    str_lit("")
                                }
                            }
                        }, n), kayak_rt::nil()))
                    } else {
                        nil::<&'static Keyed>()
                    }
                }
                _ => {
                    let other = tagcase_;
                    nil::<&'static Keyed>()
                }
            }
        } else if head_is_p(g, str_lit("hide")) {
            shared_names(cdr(items(g)))
        } else {
            nil::<&'static Keyed>()
        }
    }), its))
}

/// `e`, each `(select m x)` of a shared load's `m` the shared module's:
/// one module, so the same meaning, and one defined at the top level,
/// whose types a `select` may name (C118).
pub fn selects_renamed(e: &'static Sexp, shared: Keyeds) -> &'static Sexp {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Lst(xs, f, l, p) => {
            let to = if (head_is_p(e, str_lit("select")) && i64_eq(size(xs), 3i64)) {
                let tagcase_ = second(xs);
                match *tagcase_ {
                    Sexp::Sym(n, f2, p2) => {
                        concat(map(lambda1s(move |k: &'static Keyed| {
                            let tagcase_ = k;
                            match *tagcase_ {
                                Keyed::Keyed(m, made) => {
                                    if string_eq_p(m, n) {
                                        the::<Strings>(kayak_rt::heap_cons(made, kayak_rt::nil()))
                                    } else {
                                        nil::<Str>()
                                    }
                                }
                            }
                        }), shared))
                    }
                    _ => {
                        let other = tagcase_;
                        nil::<Str>()
                    }
                }
            } else {
                nil::<Str>()
            };
            if null_p(to) {
                lst(map(lambda1s(move |x: &'static Sexp| {
                    selects_renamed(x, shared)
                }), xs), f, l, p)
            } else {
                lst(kayak_rt::heap_cons(car(xs), kayak_rt::heap_cons(sym(car(to), f, p), kayak_rt::heap_cons(third(xs), kayak_rt::nil()))), f, l, p)
            }
        }
        _ => {
            let other = tagcase_;
            e
        }
    }
}

/// A loaded file's items: of a file of `module-parameters`, the rest, each
/// of its regions the one given; of any other, all, given nothing.
pub fn parameters_given(forms: Sexps, args: Sexps, path: Str) -> Sexps {
    if (not(null_p(forms)) && head_is_p(car(forms), str_lit("module-parameters"))) {
        let params = items(second(items(car(forms))));
        if (not(i64_eq(size(params), size(args))) || any_p(lambda1s(move |b: &'static Sexp| {
            not(sym_is_p(second(items(b)), str_lit("region")))
        }), params)) {
            error(string_append(str_lit("kfx: "), string_append(path, str_lit(": module parameters KFX gives regions alone, as many as the file has"))))
        } else {
            renamed_all(cdr(forms), map(lambda1s(move |b: &'static Sexp| {
                sym_name(car(items(b)))
            }), params), map(lambda1s(move |a: &'static Sexp| {
                let tagcase_ = a;
                match *tagcase_ {
                    Sexp::Sym(n, f, p) => {
                        n
                    }
                    _ => {
                        let other = tagcase_;
                        str_lit("?")
                    }
                }
            }), args))
        }
    } else {
        if null_p(args) {
            forms
        } else {
            error(string_append(str_lit("kfx: "), string_append(path, str_lit(": given regions, and no module-parameters"))))
        }
    }
}

/// `e`, each load in it the module its file is, shared.
pub fn spliced(e: &'static Sexp, dir: Str, loaded: Fileds, chain: Strings, known: Keyeds) -> &'static SplicedTo {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Lst(xs, f, l, p) => {
            let load = load_of(e);
            if null_p(load) {
                spliced_each(xs, dir, loaded, chain, known, nil::<&'static Sexp>(), nil::<&'static Sexp>(), f, l, p)
            } else {
                let path = {
                    let tagcase_ = car(load);
                    match *tagcase_ {
                        Sexp::Str(s, f2, p2) => {
                            if built_in_path_p(s) {
                                s
                            } else {
                                path_joined(dir, s)
                            }
                        }
                        _ => {
                            let other = tagcase_;
                            str_lit("")
                        }
                    }
                };
                let args = cdr(load);
                let key = string_append(path, string_append(str_lit(" "), show_sexps(args)));
                let had = concat(map(lambda1s(move |k: &'static Keyed| {
                    let tagcase_ = k;
                    match *tagcase_ {
                        Keyed::Keyed(kk, n) => {
                            if string_eq_p(kk, key) {
                                the::<Strings>(kayak_rt::heap_cons(n, kayak_rt::nil()))
                            } else {
                                nil::<Str>()
                            }
                        }
                    }
                }), known));
                if not(null_p(had)) {
                    spliced_to(included_module(car(had), f, l, p), nil::<&'static Sexp>(), known)
                } else {
                    let found = if built_in_path_p(path) {
                        if string_eq_p(built_in_text(path), str_lit("")) {
                            nil::<Str>()
                        } else {
                            the::<Strings>(kayak_rt::heap_cons(built_in_text(path), kayak_rt::nil()))
                        }
                    } else {
                        concat(map(lambda1s(move |x: &'static Filed| {
                            let tagcase_ = x;
                            match *tagcase_ {
                                Filed::Filed(n, text) => {
                                    if string_eq_p(n, path) {
                                        the::<Strings>(kayak_rt::heap_cons(text, kayak_rt::nil()))
                                    } else {
                                        nil::<Str>()
                                    }
                                }
                            }
                        }), loaded))
                    };
                    if string_member_p(path, chain) {
                        error(string_append(str_lit("kfx: "), string_append(f, string_append(str_lit(": a load cycle: "), words_of(reverse(the::<Strings>(kayak_rt::heap_cons(path, chain))))))))
                    } else if null_p(found) {
                        error(string_append(str_lit("kfx: cannot read "), path))
                    } else {
                        let forms = read_all(string_chars(car(found)), path, 1i64);
                        let its = parameters_given(forms, args, path);
                        let inner = spliced_each(its, directory_of(path), loaded, kayak_rt::heap_cons(path, chain), known, nil::<&'static Sexp>(), nil::<&'static Sexp>(), f, l, p);
                        let name = string_append(str_lit("made--load--"), i64_to_string(size(spliced_known(inner))));
                        let sees = map(lambda1s(move |k: &'static Keyed| {
                            let tagcase_ = k;
                            match *tagcase_ {
                                Keyed::Keyed(kk, n) => {
                                    sym(n, f, p)
                                }
                            }
                        }), spliced_known(inner));
                        let made = lst(kayak_rt::heap_cons(sym(str_lit("define"), f, p), kayak_rt::heap_cons(sym(name, f, p), kayak_rt::heap_cons(lst(kayak_rt::heap_cons(sym(str_lit("module"), f, p), kayak_rt::heap_cons(lst(kayak_rt::heap_cons(sym(str_lit("%loaded"), f, p), kayak_rt::heap_cons(str(path, f, p), sees)), f, l, p), items(spliced_form(inner)))), f, l, p), kayak_rt::nil()))), f, l, p);
                        spliced_to(included_module(name, f, l, p), onto(spliced_defs(inner), kayak_rt::heap_cons(made, kayak_rt::nil())), kayak_rt::heap_cons(keyed(key, name), spliced_known(inner)))
                    }
                }
            }
        }
        _ => {
            let other = tagcase_;
            spliced_to(e, nil::<&'static Sexp>(), known)
        }
    }
}

/// Each of `xs` spliced in turn, `done` those so far, reversed.
pub fn spliced_each(mut xs: Sexps, mut dir: Str, mut loaded: Fileds, mut chain: Strings, mut known: Keyeds, mut done: Sexps, mut defs: Sexps, mut f: Str, mut l: i64, mut p: i64) -> &'static SplicedTo {
    loop {
        if null_p(xs) {
            let its = the::<Sexps>(reverse(done));
            let shared = shared_names(its);
            return spliced_to(lst(if null_p(shared) {
                its
            } else {
                map(lambda1s(move |x: &'static Sexp| {
                    selects_renamed(x, shared)
                }), its)
            }, f, l, p), defs, known);
        } else {
            let tagcase_ = spliced(car(xs), dir, loaded, chain, known);
            match *tagcase_ {
                SplicedTo::SplicedTo(x, more, known2) => {
                    (xs, known, done, defs) = (cdr(xs), known2, kayak_rt::heap_cons(x, done), onto(defs, more));
                    continue;
                }
            }
        }
    }
}

// A module made where it is included or extended (C90): FX-26 makes it
// before the module's items, seeing none of them, so it is defined before
// the module that uses it, at the top level, named `made--P` (`P` where it
// is written), a name no KFX name is (C27's `--`), and used by that name.
pub fn made_name(e: &'static Sexp) -> Str {
    string_append(str_lit("made--"), i64_to_string(datum_pos(e)))
}

pub fn made_here_p(e: &'static Sexp) -> bool {
    head_is_p(e, str_lit("module"))
}

/// The modules made in place among a module's items, each defined.
pub fn made_in(its: Sexps) -> Sexps {
    concat(map(lambda1s(move |g: &'static Sexp| {
        if (head_is_p(g, str_lit("include")) && made_here_p(second(items(g)))) {
            the::<Sexps>(kayak_rt::heap_cons(lst(kayak_rt::heap_cons(sym(str_lit("define"), str_lit(""), 0i64), kayak_rt::heap_cons(sym(made_name(second(items(g))), str_lit(""), 0i64), kayak_rt::heap_cons(second(items(g)), kayak_rt::nil()))), str_lit(""), 0i64, 0i64), kayak_rt::nil()))
        } else if head_is_p(g, str_lit("hide")) {
            made_in(cdr(items(g)))
        } else {
            nil::<&'static Sexp>()
        }
    }), its))
}

/// A module's items, each module made in place named.
pub fn named_made(its: Sexps) -> Sexps {
    map(lambda1s(move |g: &'static Sexp| {
        if (head_is_p(g, str_lit("include")) && made_here_p(second(items(g)))) {
            lst(kayak_rt::heap_cons(car(items(g)), kayak_rt::heap_cons(sym(made_name(second(items(g))), str_lit(""), 0i64), cdr(cdr(items(g))))), str_lit(""), 0i64, 0i64)
        } else if head_is_p(g, str_lit("hide")) {
            lst(kayak_rt::heap_cons(car(items(g)), named_made(cdr(items(g)))), str_lit(""), 0i64, 0i64)
        } else {
            g
        }
    }), its)
}

/// A top-level form, after the modules it makes in place, each defined.
pub fn hoisted(f: &'static Sexp) -> Sexps {
    if not(module_def_p(f)) {
        the::<Sexps>(kayak_rt::heap_cons(f, kayak_rt::nil()))
    } else {
        let tagcase_ = f;
        match *tagcase_ {
            Sexp::Lst(xs, file, line, pos) => {
                let x = third(xs);
                if head_is_p(x, str_lit("module")) {
                    onto(made_in(cdr(items(x))), the::<Sexps>(kayak_rt::heap_cons(lst(kayak_rt::heap_cons(car(xs), kayak_rt::heap_cons(second(xs), kayak_rt::heap_cons(lst(kayak_rt::heap_cons(car(items(x)), named_made(cdr(items(x)))), file, line, pos), kayak_rt::nil()))), file, line, pos), kayak_rt::nil())))
                } else if head_is_p(x, str_lit("extend")) {
                    let ys = items(x);
                    let e0 = second(ys);
                    if made_here_p(e0) {
                        the::<Sexps>(kayak_rt::heap_cons(lst(kayak_rt::heap_cons(sym(str_lit("define"), str_lit(""), 0i64), kayak_rt::heap_cons(sym(made_name(e0), str_lit(""), 0i64), kayak_rt::heap_cons(e0, kayak_rt::nil()))), str_lit(""), 0i64, 0i64), kayak_rt::heap_cons(lst(kayak_rt::heap_cons(car(xs), kayak_rt::heap_cons(second(xs), kayak_rt::heap_cons(lst(kayak_rt::heap_cons(car(ys), kayak_rt::heap_cons(sym(made_name(e0), str_lit(""), 0i64), kayak_rt::heap_cons(third(ys), kayak_rt::nil()))), file, line, pos), kayak_rt::nil()))), file, line, pos), kayak_rt::nil())))
                    } else {
                        the::<Sexps>(kayak_rt::heap_cons(f, kayak_rt::nil()))
                    }
                } else {
                    the::<Sexps>(kayak_rt::heap_cons(f, kayak_rt::nil()))
                }
            }
            _ => {
                let other = tagcase_;
                the::<Sexps>(kayak_rt::heap_cons(f, kayak_rt::nil()))
            }
        }
    }
}

/// A `plambda` directly in a `plambda`, as FX-26's library writes one
/// whose type is a `poly` in a `poly` (C70, C107): one, the binders in
/// order.
pub fn flat_plambda(e: &'static Sexp) -> &'static Sexp {
    if (head_is_p(e, str_lit("plambda")) && i64_eq(size(items(e)), 3i64) && head_is_p(third(items(e)), str_lit("plambda"))) {
        let inner = flat_plambda(third(items(e)));
        lst(kayak_rt::heap_cons(car(items(e)), kayak_rt::heap_cons(lst(onto(items(second(items(e))), items(second(items(inner)))), str_lit(""), 0i64, 0i64), kayak_rt::heap_cons(third(items(inner)), kayak_rt::nil()))), datum_file(e), 0i64, datum_pos(e))
    } else {
        e
    }
}

/// A definition whose type is a `poly` in a `poly` and whose value a
/// `plambda` in a `plambda`, as one of each; a module's, each of its
/// items'.
pub fn flat_definition(f: &'static Sexp) -> &'static Sexp {
    let tagcase_ = f;
    match *tagcase_ {
        Sexp::Lst(xs, file, line, pos) => {
            if ((head_is_p(f, str_lit("define")) || head_is_p(f, str_lit("define*"))) && i64_eq(size(xs), 4i64)) {
                lst(kayak_rt::heap_cons(car(xs), kayak_rt::heap_cons(second(xs), kayak_rt::heap_cons(flat_poly(third(xs)), kayak_rt::heap_cons(flat_plambda(fourth(xs)), kayak_rt::nil())))), file, line, pos)
            } else if head_is_p(f, str_lit("define-rec")) {
                lst(kayak_rt::heap_cons(car(xs), map(lambda1s(move |m: &'static Sexp| {
                    let tagcase_ = m;
                    match *tagcase_ {
                        Sexp::Lst(ys, f2, l2, p2) => {
                            if i64_eq(size(ys), 3i64) {
                                lst(kayak_rt::heap_cons(car(ys), kayak_rt::heap_cons(flat_poly(second(ys)), kayak_rt::heap_cons(flat_plambda(third(ys)), kayak_rt::nil()))), f2, l2, p2)
                            } else {
                                m
                            }
                        }
                        _ => {
                            let other = tagcase_;
                            m
                        }
                    }
                }), cdr(xs))), file, line, pos)
            } else if (head_is_p(f, str_lit("module")) || head_is_p(f, str_lit("hide"))) {
                lst(kayak_rt::heap_cons(car(xs), map(&flat_definition, cdr(xs))), file, line, pos)
            } else if (head_is_p(f, str_lit("define")) && i64_eq(size(xs), 3i64) && head_is_p(third(xs), str_lit("module"))) {
                lst(kayak_rt::heap_cons(car(xs), kayak_rt::heap_cons(second(xs), kayak_rt::heap_cons(flat_definition(third(xs)), kayak_rt::nil()))), file, line, pos)
            } else {
                f
            }
        }
        _ => {
            let other = tagcase_;
            f
        }
    }
}

/// `e`, each `load-module` of a path of a file its path from `dir`, the
/// directory of the file `e` was read from (C116: a `load-input`'s
/// file's, whose forms are read where the program is).
pub fn loads_from(e: &'static Sexp, dir: Str) -> &'static Sexp {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Lst(xs, f, l, p) => {
            if (head_is_p(e, str_lit("load-module")) && i64_eq(size(xs), 2i64)) {
                let tagcase_ = second(xs);
                match *tagcase_ {
                    Sexp::Str(t, f2, p2) => {
                        if built_in_path_p(t) {
                            e
                        } else {
                            lst(kayak_rt::heap_cons(car(xs), kayak_rt::heap_cons(str(path_joined(dir, t), f2, p2), kayak_rt::nil())), f, l, p)
                        }
                    }
                    _ => {
                        let other = tagcase_;
                        e
                    }
                }
            } else {
                lst(map(lambda1s(move |x: &'static Sexp| {
                    loads_from(x, dir)
                }), xs), f, l, p)
            }
        }
        _ => {
            let other = tagcase_;
            e
        }
    }
}

/// `(define x (load-input "fx26:p"))` (C116, FX-26's M7): the built-in
/// file's one expression, as Fixpt's code generators are written: a
/// module, or a `let` of loaded modules around one. The module is a
/// loaded one, which sees the standard environment alone; the `let`'s
/// modules are defined before it, each `made--input--P--n` (`P` where the
/// load is), which it alone sees, by that name. A file of the program's
/// from the loading file's directory, as `load-module`'s.
pub fn input_expanded(f: &'static Sexp, dir: Str, loaded: Fileds) -> Sexps {
    let tagcase_ = f;
    match *tagcase_ {
        Sexp::Lst(xs, fl, l, p) => {
            if (head_is_p(f, str_lit("define")) && i64_eq(size(xs), 3i64) && head_is_p(third(xs), str_lit("load-input"))) {
                let load = items(third(xs));
                let written = {
                    let tagcase_ = second(load);
                    match *tagcase_ {
                        Sexp::Str(t, f2, p2) => {
                            t
                        }
                        _ => {
                            let other = tagcase_;
                            str_lit("")
                        }
                    }
                };
                let path = if built_in_path_p(written) {
                    written
                } else {
                    path_joined(dir, written)
                };
                let text = if built_in_path_p(path) {
                    built_in_text(path)
                } else {
                    let found = concat(map(lambda1s(move |x: &'static Filed| {
                        let tagcase_ = x;
                        match *tagcase_ {
                            Filed::Filed(n, t) => {
                                if string_eq_p(n, path) {
                                    the::<Strings>(kayak_rt::heap_cons(t, kayak_rt::nil()))
                                } else {
                                    nil::<Str>()
                                }
                            }
                        }
                    }), loaded));
                    if null_p(found) {
                        str_lit("")
                    } else {
                        car(found)
                    }
                };
                let es = if string_eq_p(text, str_lit("")) {
                    error(string_append(str_lit("kfx: "), string_append(fl, string_append(str_lit(": cannot read "), path))))
                } else {
                    map(lambda1s(move |x: &'static Sexp| {
                        if built_in_path_p(path) {
                            x
                        } else {
                            loads_from(x, directory_of(path))
                        }
                    }), read_all(string_chars(text), path, 1i64))
                };
                let e = if i64_eq(size(es), 1i64) {
                    car(es)
                } else {
                    error(string_append(str_lit("kfx: "), string_append(path, str_lit(": not a file of one expression"))))
                };
                let bound = if head_is_p(e, str_lit("let")) {
                    items(second(items(e)))
                } else {
                    nil::<&'static Sexp>()
                };
                let body = if head_is_p(e, str_lit("let")) {
                    third(items(e))
                } else {
                    e
                };
                let names = map(lambda1s(move |b: &'static Sexp| {
                    sym_name(car(items(b)))
                }), bound);
                let lifted = map(lambda1s(move |n: Str| {
                    string_append(str_lit("made--input--"), string_append(i64_to_string(datum_pos(third(xs))), string_append(str_lit("--"), n)))
                }), names);
                if (not(head_is_p(body, str_lit("module"))) || (head_is_p(e, str_lit("let")) && not(i64_eq(size(items(e)), 3i64))) || any_p(lambda1s(move |b: &'static Sexp| {
                    not(head_is_p(second(items(b)), str_lit("load-module")))
                }), bound)) {
                    error(string_append(str_lit("kfx: "), string_append(path, str_lit(": a load-input of what KFX reads not yet: a module, or a let of loaded modules around one"))))
                } else {
                    onto(map2(lambda2s(move |b: &'static Sexp, n: Str| {
                        lst(kayak_rt::heap_cons(sym(str_lit("define"), fl, p), kayak_rt::heap_cons(sym(n, fl, p), kayak_rt::heap_cons(second(items(b)), kayak_rt::nil()))), fl, l, p)
                    }), bound, lifted), kayak_rt::heap_cons(lst(kayak_rt::heap_cons(car(xs), kayak_rt::heap_cons(second(xs), kayak_rt::heap_cons(lst(kayak_rt::heap_cons(sym(str_lit("module"), fl, p), kayak_rt::heap_cons(lst(kayak_rt::heap_cons(sym(str_lit("%loaded"), fl, p), kayak_rt::heap_cons(str(path, fl, p), map(lambda1s(move |n: Str| {
                        sym(n, fl, p)
                    }), lifted))), fl, l, p), renamed_all(cdr(items(body)), names, lifted))), fl, l, p), kayak_rt::nil()))), fl, l, p), kayak_rt::nil()))
                }
            } else {
                kayak_rt::heap_cons(f, kayak_rt::nil())
            }
        }
        _ => {
            let other = tagcase_;
            kayak_rt::heap_cons(f, kayak_rt::nil())
        }
    }
}

/// The program's forms, each load shared, the modules each first makes
/// defined before it.
pub fn spliced_tops(forms: Sexps, dir: Str, loaded: Fileds, known: Keyeds) -> Sexps {
    if null_p(forms) {
        nil::<&'static Sexp>()
    } else {
        let tagcase_ = spliced(car(forms), dir, loaded, nil::<Str>(), known);
        match *tagcase_ {
            SplicedTo::SplicedTo(x, defs, known2) => {
                onto(defs, kayak_rt::heap_cons(x, spliced_tops(cdr(forms), dir, loaded, known2)))
            }
        }
    }
}

/// A program's forms: what it loads spliced in (C88), and what its modules
/// make in place defined before them (C90); a `poly` in a `poly` around a
/// definition, one (C107); a `load-input` of a module, the module (C116).
pub fn with_loads(forms: Sexps, file: Str, loaded: Fileds) -> Sexps {
    let forms = concat(map(lambda1s(move |f: &'static Sexp| {
        input_expanded(f, directory_of(file), loaded)
    }), forms));
    map(&flat_definition, concat(map(&hoisted, if (null_p(loaded) && not(any_p(&loads_p, forms))) {
        forms
    } else {
        spliced_tops(forms, directory_of(file), loaded, nil::<&'static Keyed>())
    })))
}

